</template>

<script setup>
import { ref, computed, onMounted } from 'vue'
import { useRoute } from 'vue-router'
import { knowledgeApi } from '@/api'

const route = useRoute()
const loading = ref(true)
const error = ref(null)
const article = ref({ title: '加载中...', views: 0, content: '' })
const contactVisible = ref(false)

const copyWechat = () => {
  navigator.clipboard.writeText('bingge_jiangjiu').then(() => {
    alert('微信号已复制！打开微信搜索添加')
  }).catch(() => {
    alert('微信号：bingge_jiangjiu')
  })
}

const formatViews = (v) => v >= 10000 ? (v/10000).toFixed(1)+'万' : String(v||0)

const parseMarkdown = (text) => {
  if (!text || typeof text !== 'string') return ''
  
  let html = text
    // Headers: ## → h3, ### → h4
    .replace(/^### (.+)$/gm, '<h4>$1</h4>')
    .replace(/^## (.+)$/gm, '<h3>$1</h3>')
    // Bold
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    // Italic
    .replace(/\*(.+?)\*/g, '<em>$1</em>')
    // List items
    .replace(/^- (.+)$/gm, '<li>$1</li>')
    // Tables (simple: convert rows with |)
    .replace(/^\|(.+)\|$/gm, (match) => {
      const cells = match.split('|').filter(c => c.trim())
      if (cells.length >= 2) {
        return '<div class="data-row"><span>' + cells.map(c => c.trim()).join('</span><span>') + '</span></div>'
      }
      return match
    })
    // Separators (---|---)
    .replace(/^\|[-| ]+\|$/gm, '')
    // Blockquotes
    .replace(/^\* (.+)$/gm, '<blockquote>$1</blockquote>')
    // Paragraphs (double newline)
    .replace(/\n\n/g, '</p><p>')
    // Single newlines
    .replace(/\n/g, '<br>')
  
  // Wrap lists
  html = html.replace(/(<li>.*?<\/li>)/gs, (match) => {
    if (!match.includes('</ul>')) {
      return '<ul>' + match + '</ul>'
    }
    return match
  })
  
  // Clean up empty <p>s
  html = html.replace(/<p><\/p>/g, '')
  html = html.replace(/<p><br><\/p>/g, '')
  
  return '<p>' + html + '</p>'
}

const renderedContent = computed(() => {
  return parseMarkdown(article.value.content)
})

onMounted(async () => {
  try {
    const res = await knowledgeApi.getDetail(route.params.id)
    if (res.code === 200 && res.data) {
      article.value = res.data
    } else {
      article.value = { title: '文章不存在', author: '', views: 0, content: '抱歉，您访问的文章不存在。' }
    }
  } catch (e) {
    // 后端不可用时使用本地数据
    const localArticles = {
      'klg_001': { id: 'klg_001', title: `酱酒历史溯源：从远古到现代的千年传承`, author: `酱酒知识库`, icon: `📜`, views: 15678, content: `酱酒历史可追溯至秦汉时期。《史记》记载，西汉建元六年（公元前135年），唐蒙出使南越，在夜郎国尝到\'枸酱酒\'，惊叹其味，带回长安献给汉武帝，这是关于酱酒最早的文字记载。  ## 唐宋发展 唐宋时期，赤水河流域酿酒技术日趋成熟。茅台镇一带已出现规模化酿酒作坊，\'风曲法酒\'等酿造工艺开始形成。  ## 明清成熟 明清时期是酱酒工艺定型的关键时期。\'回沙\'工艺出现，标志着酱酒酿造技术走向成熟。成义、荣和、恒兴三大烧房相继创立，茅台酒名声渐起。  ## 现代辉煌 1915年，茅台酒在巴拿马万国博览会获得金奖，中国白酒首次获得国际认可。1951年，三家烧房合并组建国营茅台酒厂。2006年，茅台酒酿制技艺入选首批国家级非物质文化遗产名录。  如今，酱酒产业已成为中国白酒的重要支柱，2025年市场规模突破3000亿元。` },
      'klg_002': { id: 'klg_002', title: `端午制曲：酱酒酿造的第一道神秘工序`, author: `酱酒知识库`, icon: `🌾`, views: 12345, content: `端午制曲，是酱酒一年生产周期的起点。每年端午时节（公历5-6月），茅台镇气温升至30°C以上，湿度增大，空气中微生物最为活跃。  ## 为什么选择端午 端午时节的自然条件创造了制曲的最佳环境： - 气温高：30°C以上，利于微生物繁殖 - 湿度大：提供充足水分 - 原料佳：冬小麦刚收割，颗粒饱满  ## 制曲流程 小麦粉碎→加水拌料→踩制成型→入仓发酵→翻仓晾霉→高温培菌→出仓储存 一块合格的曲需要40天才能成熟，再存放半年以上方可使用。  ## 踩曲文化 茅台镇至今保留女子踩曲的传统。踩曲女工们脚踩龟背形曲块，用身体的温度和力度让曲料成型。这道工序既需要技巧也需要体力，已被视为茅台镇独特的文化景观。  ## 曲为酒之骨 大曲中的微生物（芽孢杆菌、酵母菌等）产生丰富的酶类和香气前驱物，决定了酱酒的骨架和风味。酱酒用曲量高达原料的100%，是所有白酒中最高的。` },
      'klg_003': { id: 'klg_003', title: `重阳下沙：开启一年的酿酒之旅`, author: `酱酒知识库`, icon: `🍂`, views: 10234, content: `重阳下沙是酱酒酿造的第一次投料环节，也是全年生产周期中最具仪式感的时刻。  ## 为什么是重阳 - 红缨子高粱正值成熟期，支链淀粉含量高达88% - 雨季结束，赤水河水质清澈甘甜 - 秋高气爽，气温适中（18-25°C），利于发酵启动 - 重阳节本身寓意\'步步高升\'，中国人讲究好日子开工  ## 下沙流程 润粮（热水浸润高粱8-10小时）→蒸粮（蒸煮至七成熟）→摊凉→加曲→堆积发酵（有氧发酵，温度升至50°C+）→入窖发酵（厌氧发酵30天）。  ## 红缨子高粱 这种特产于仁怀地区的小红高粱是坤沙工艺的\'秘密武器\'： - 颗粒小、皮厚、耐蒸煮 - 支链淀粉含量≥88%，保证九次蒸煮不糊烂 - 单宁含量1.5-2.0%，发酵中转化为独特香气` },
      'klg_004': { id: 'klg_004', title: `赤水河：一条流淌着美酒的传奇河流`, author: `酱酒知识库`, icon: `🌊`, views: 11678, content: `赤水河发源于云南省镇雄县，流经贵州、四川两省，全长436.5公里，是长江上游唯一未建水坝的一级支流。  ## \'美酒河\'密码 - 水质清冽，富含钙、镁等矿物质 - pH值7.2-7.8，呈弱碱性，是酿酒的理想水质 - 雨季河水呈赤红色（冲刷红色砂岩），酿酒季变为清澈 - 沿岸森林覆盖率55%以上，生态环境优良  ## 美酒河谷 赤水河畔分布着数千家酒厂，形成了世界级的白酒酿造带： - 茅台镇：酱酒核心产区 - 习水镇：习酒大本营 - 二郎镇：郎酒根据地 - 金沙县：新兴酱酒重镇  ## \'异地茅台\'的失败 20世纪70年代，国家曾组织\'异地茅台实验\'——将茅台酒厂的工艺、工匠、原料甚至窖泥全部搬至遵义市郊，但酿出的酒始终达不到茅台酒的品质。这一实验从科学上证明了赤水河茅台镇地理环境的不可复制性。` },
      'klg_005': { id: 'klg_005', title: `茅台镇：不可复制的微生物王国`, author: `酱酒知识库`, icon: `🔬`, views: 9876, content: `茅台镇位于北纬27°51\'，东经105°，静卧于海拔400米左右的赤水河谷，形成\'两山对峙、一水中流\'的封闭河谷地貌。  ## 神奇的微气候 - 年均气温16.3°C，夏季闷热潮湿，冬季温和 - 空气流动性弱，湿度常年保持在78%左右 - 温差小，形成了稳定的微生物繁衍环境  ## 微生物王国 茅台酒的酿造环境和过程中，已发现1946种微生物（1063种细菌，883种酵母菌和丝状真菌）。在15.03平方公里的茅台核心产区，存在超过3300个属的微生物。  科学家还发现了两株全球全新的梭菌菌种：\'石窖梭菌\'和\'茅台梭菌\'，这些特殊菌种是茅台酒独特风味的重要贡献者。  ## 三位一体生态系统 \'紫色砂页岩地质 + 亚热带季风气候 + 微生物群落\'共同构成了不可复制的酿造环境。这也是为什么\'异地茅台\'实验会失败——离开茅台镇这片土地，同样的工艺和工匠，也酿造不出同样的酒。` },
      'klg_006': { id: 'klg_006', title: `红缨子高粱：酱酒的核心秘密`, author: `酱酒知识库`, icon: `🌾`, views: 8765, content: `红缨子高粱，又称小红粱，是仁怀及周边赤水河流域特产的高粱品种，被视为酱酒的\'灵魂原料\'。  ## 品种特征 - 颗粒小：只有普通高粱一半大小 - 皮厚：角质层厚，耐九次蒸煮不破碎 - 色红：呈红褐色，故称\'红缨子\' - 支链淀粉含量≥88%：这是酱酒耐蒸煮的关键 - 单宁含量1.5-2.0%：发酵中转化为复杂香气物质  ## 为什么不能用普通高粱 普通高粱支链淀粉含量低，蒸煮2-3次就会糊烂。而坤沙工艺需要九次蒸煮，只有红缨子高粱能承受这样的反复蒸煮，保证每次都能提取出新的风味物质。  ## 种植现状 红缨子高粱主要种植于仁怀、习水、金沙等赤水河流域县市，总面积约200万亩。茅台集团建立了严格的有机种植基地，不施化肥农药，从源头把控品质。` },
      'klg_007': { id: 'klg_007', title: `陶坛储酒：时间的艺术，岁月的魔法`, author: `酱酒知识库`, icon: `⏳`, views: 10567, content: `酱酒酿造的最后一道工序是储存。基酒必须在陶坛中陈放三年以上，才能勾调出厂。  ## 为什么是陶坛 - 陶坛具有微孔结构，允许微量氧气透过，促进缓慢氧化 - 陶土中的钙、镁、铁等金属离子能催化老熟反应 - 化学性质稳定，不与酒液发生不良反应 - 这是中国白酒千年传承的智慧  ## 储存条件 - 温度：15-25°C - 湿度：60-80% - 环境：避光、通风 - 基酒储存：3年以上 - 成品酒建议：5年以上陈放口感最佳  ## 老熟过程中的变化 1. 挥发：低沸点刺激性物质（醛类、硫化物）逐渐挥发 2. 氧化：醇类氧化为醛，醛再氧化为酸 3. 酯化：醇与酸反应生成酯类（香气物质） 4. 缔合：乙醇分子与水分子形成稳定缔合体，口感更绵柔  经过5年以上的储存，新酒的辛辣转为绵柔醇厚，酱香更加突出，回味更加悠长。这正是\'酒是陈的香\'的科学解释。` },
      'klg_008': { id: 'klg_008', title: `茅台酒节：千年祭祀传统的现代传承`, author: `酱酒知识库`, icon: `🏮`, views: 7890, content: `茅台酒节是茅台镇最具代表性的传统文化活动，源自古代酿酒行业祭祀酒神杜康、敬拜天地自然的传统。  ## 历史渊源 中国古代酿酒业历来有祭祀传统。酿酒工匠在每年开工前都要祭拜酒神、天地，祈求风调雨顺、酿出好酒。茅台镇将这一传统延续至今，并赋予其新的时代内涵。  ## 现代茅台酒节 - 时间：重阳节前后（每年10月） - 仪式：祭酒神→敬天地→拜先贤→祈丰收 - 参与者：茅台酒厂及茅台镇数千家酒企共同参与 - 文化意义：感恩自然恩赐，敬畏传统工艺  ## 非遗价值 2006年，茅台酒酿制技艺入选国家级非遗。茅台酒节作为这一非遗的重要组成部分，展现了中华民族尊重自然、传承匠心的深厚文化底蕴。  茅台官网文化板块设有\'茅台酒节\'专题，详细记录了每一届酒节的盛况。` },
      'klg_009': { id: 'klg_009', title: `茅台玖章：一部酱酒文化的百科全书`, author: `酱酒知识库`, icon: `📖`, views: 13567, content: `\'茅台玖章\'是茅台集团打造的企业文化体系，以九个章节系统性地阐述了茅台的历史传承、文化精神、质量理念和社会责任。  ## 九章内容 1. 历史传承：从枸酱酒到国酒茅台的千年历程 2. 品质密码：12987工艺与质量管理体系 3. 生态理念：赤水河流域生态保护的茅台实践 4. 文化精神：\'爱我茅台，为国争光\'的企业精神 5. 社会责任：国之栋梁公益项目 6. 工匠精神：茅台工匠的培养与传承 7. 创新驱动：传统工艺的科技赋能 8. 品牌价值：茅台品牌的全球化之路 9. 未来愿景：茅台的世界一流企业目标  ## 茅台玖章的意义 茅台玖章不仅是企业文化的提炼，更是中国白酒行业文化建设的标杆。它将抽象的\'酒文化\'系统化、可视化，让消费者更深入地理解茅台的产品价值和品牌内涵。` },
      'klg_010': { id: 'klg_010', title: `中国酱酒产区地图：认识核心产区`, author: `酱酒知识库`, icon: `🗺️`, views: 14567, content: `中国酱酒核心产区集中在赤水河流域，从上游到下游分布着多个特色产区。  ## 茅台镇核心产区（仁怀） - 面积：15.03平方公里 - 特点：酱酒核心中的核心，不可复制的微生物环境 - 代表：茅台、国台、钓鱼台  ## 习水产区 - 位置：赤水河中上游 - 特点：气候与茅台镇相近，水质优良 - 代表：习酒、安酒  ## 二郎镇产区（古蔺） - 位置：赤水河左岸，四川古蔺县 - 特点：与茅台镇隔河相望，共享地理优势 - 代表：郎酒  ## 金沙产区 - 位置：毕节市金沙县 - 特点：酱酒新兴力量，发展迅猛 - 代表：金沙回沙酒（已被华润收购）  ## 遵义产区（大产区概念） - 涵盖仁怀、习水、播州等区县 - 2025年产值突破1000亿元 - 占全国酱酒产值的60%以上  每个产区因地理、气候、水源的微妙差异，酿造出的酱酒各有特色，形成了丰富多彩的酱酒世界。` },
      'klg_011': { id: 'klg_011', title: `12987工艺详解：酱酒酿造的核心密码`, author: `酱酒知识库`, icon: `📖`, views: 18765, content: `12987工艺是坤沙酱酒的数字密码，也是中国白酒最复杂的酿造工艺。  ## 1年：一个完整生产周期 从端午制曲开始，到次年第七轮次取酒结束，整整一年。所有白酒中，酱酒的生产周期最长。  ## 2次：两次投料 - 第一次：重阳下沙，投入50%的高粱 - 第二次：一个月后糙沙，投入剩余50%的高粱  ## 9次：九次蒸煮 每轮次蒸煮后都要摊凉、加曲、堆积发酵、入窖发酵，循环往复。高粱经过九次蒸煮，营养物质被充分提取。  ## 8次：八次发酵 - 堆积发酵（有氧）：堆温可达50°C以上，微生物大量繁殖 - 窖池发酵（厌氧）：在石窖中密闭发酵30天  ## 7次：七次取酒 从第三次蒸煮后开始取酒，每轮次的酒风格各异： - 1-2轮次：生粮香，酸涩 - 3-5轮次：酱香突出，醇厚丰满（黄金轮次） - 6-7轮次：焦香糊香，微苦  七个轮次的酒经过调酒师的妙手勾调，最终形成\'酱香突出、优雅细腻、酒体醇厚、回味悠长\'的经典风格。` },
      'klg_012': { id: 'klg_012', title: `四高两长：酱酒工艺的核心特点`, author: `酱酒知识库`, icon: `🔥`, views: 13456, content: `\'四高两长\'是酱酒工艺区别于其他香型白酒的核心特征。  ## 高温制曲（60-65°C） 在所有白酒中，酱酒制曲温度最高。高温筛选出耐热芽孢杆菌，产生丰富的吡嗪类、呋喃类化合物，赋予酱酒独特的酱香和焦香。  ## 高温堆积（50°C以上） 加曲后的高粱堆成圆锥体进行有氧发酵，堆子中心温度可达50°C以上。这是酱酒工艺独有的工序，被称为\'二次制曲\'——堆积过程中微生物大量繁殖并产生香气前驱物。  ## 高温发酵（35-38°C） 入窖发酵温度也比其他香型高。高温厌氧发酵产生了大量的有机酸和酯类物质。  ## 高温馏酒（接酒温度40°C以上） 接酒温度高有利于高沸点香气物质提取，同时排出低沸点刺激性物质（醛类、甲醇等），使酒体更加纯净。  ## 两长 - 生产周期长：一年一个周期 - 贮存时间长：基酒至少3年，成品酒5年以上` },
      'klg_013': { id: 'klg_013', title: `七轮次取酒：每一轮都有独特风味`, author: `酱酒知识库`, icon: `🍷`, views: 12456, content: `七轮次取酒是坤沙工艺最具特色的环节，每个轮次的基酒都有独特的风格和用途。  ## 各轮次特点 | 轮次 | 取酒时间 | 风味特征 | 酒精度 | 占比 | |------|----------|----------|--------|------| | 一轮次 | 12月-1月 | 生粮香突出，酸涩味重 | ≥57% | 约5% | | 二轮次 | 1月-2月 | 甜香明显，略带酸涩 | ≥54% | 约8% | | 三轮次 | 2月-3月 | 酱香初显，醇和微甜 | ≥53% | 约20% | | 四轮次 | 3月-4月 | 酱香突出，醇厚饱满 | ≥53% | 约25% | | 五轮次 | 4月-5月 | 酱香焦香，回味悠长 | ≥53% | 约22% | | 六轮次 | 5月-6月 | 焦香糊香，微有苦味 | ≥52% | 约15% | | 七轮次 | 6月-7月 | 糊香突出，苦味明显 | ≥52% | 约5% |  ## 盘勾艺术 七轮次酒不能单独饮用，必须由调酒师按科学比例进行\'盘勾\'——将不同轮次、不同香型（酱香、醇甜、窖底香）的基酒精心组合，再加上调味酒点睛，才能达到完美的平衡。  三四五轮次被称为\'黄金轮次\'，是酱酒品质的核心支撑。` },
      'klg_014': { id: 'klg_014', title: `坤沙、翻沙、碎沙、窜沙：酱酒的四种工艺等级`, author: `酱酒知识库`, icon: `📊`, views: 16789, content: `酱酒按酿造工艺分为四个等级，品质和价格差异巨大。了解这四种工艺，是选购酱酒的基本功。  ## 坤沙（顶级） - 原料：完整红缨子高粱，破碎率≤20% - 工艺：完整12987工艺 - 周期：一年 - 出酒率：约20%（约5斤粮食（高粱和大曲各占一半）出一斤酒） - 品质：最高，酱香突出，酒体醇厚 - 代表：飞天茅台 - 价格：500元以上  ## 翻沙（中高端） - 原料：坤沙酒糟+新高粱 - 工艺：利用坤沙七次取酒后的酒糟，加入新高粱和高温大曲再次发酵蒸馏 - 本质：理论上是坤沙的第八次取酒 - 口感：虽然品质不及纯坤沙，但口感仍属于坤沙等级，酱香明显 - 周期：较短，约1-2个月 - 出酒率：较高 - 价格：200-500元  ## 碎沙（中端） - 原料：粉碎的高粱（打成粉） - 工艺：完全不同于坤沙的简化工艺，高粱粉碎后发酵方式改变 - 特点：工艺已完全改变，高粱打成粉后口感和风格也随之改变 - 周期：3-6个月 - 出酒率：40-60% - 口感：香气直接柔顺，但缺乏坤沙的层次感和复杂度 - 品质低于翻沙，因为翻沙至少保留了坤沙的底子 - 价格：150-350元  ## 窜沙（低端） - 工艺：用食用酒精蒸馏坤沙酒糟，取酒糟的香气 - 品质：最差，严格说不能算酱酒 - 价格：100元以下 - 建议：不要购买  ## 为什么翻沙排在碎沙之上 翻沙虽然用的不是新粮，但它是在坤沙酒糟的基础上继续发酵——相当于坤沙工艺的延续。坤沙七次取酒后，酒糟中仍有大量残余淀粉和风味物质，翻沙将这些精华再次提取，所以口感仍属于坤沙等级。  碎沙则完全不同——高粱打成粉后，发酵方式和风味形成路径都改变了，已经不属于坤沙体系。  ## 辨别方法 - 坤沙酒：挂杯明显，空杯留香24小时以上 - 翻沙酒：酱香明显，但留香时间较短 - 碎沙酒：香气直接但层次单薄，留香短 - 窜沙酒：闻香有酒精刺鼻感` },
      'klg_015': { id: 'klg_015', title: `勾调艺术：酱酒的画龙点睛之笔`, author: `酱酒知识库`, icon: `🎨`, views: 14567, content: `勾调是酱酒品质的最后一道关口，也是最具技术含量的环节。  ## 什么是勾调 将不同轮次（1-7轮）、不同年份（3年-30年+）、不同香型（酱香、醇甜、窖底香）的基酒，按照科学比例混合，使酒体达到最佳平衡状态。  ## 勾调三阶段 1. 小盘勾：调酒师在小样中反复试验，确定配方 2. 大盘勾：按小样配方大量勾调（数以吨计） 3. 调味：加入1%-5%的调味酒（老酒）画龙点睛  ## 勾调师 顶级勾调师需要10年以上经验，能够辨别2000多种风味物质。他们的大脑就像一个超级\'数据库\'，储存着每一批基酒的风格特征。  ## 季克良：中国酱酒勾调第一人 茅台集团前董事长季克良是中国最著名的酱酒勾调大师。他提出\'离开了茅台镇就酿不出茅台酒\'的著名论断，并将毕生精力奉献给茅台酒的品质提升。在他的带领下，茅台酒从年产几百吨发展到数万吨，品质始终如一。  ## 常见误解 勾调≠勾兑。勾调是酱酒工艺的核心环节，是\'以酒调酒\'；而\'三精一水\'（酒精+香精+糖精+水）是造假行为，两者本质不同。` },
      'klg_016': { id: 'klg_016', title: `石窖发酵：酱酒的摇篮`, author: `酱酒知识库`, icon: `🏛️`, views: 9876, content: `石窖发酵是酱酒区别于浓香型白酒（用泥窖）的重要工艺特征。  ## 石窖构造 - 窖壁：用当地红砂石砌成 - 窖底：铺黄泥 - 尺寸：约4m×2m×2.5m - 材质特点：砂石具有微孔结构，透气性好  ## 为什么用石窖 - 砂石透气但不透水，有利于厌氧发酵环境控制 - 石壁中的矿物质（钙、镁、铁）参与发酵反应 - 窖底黄泥中的微生物群落丰富，越老的窖越好 - 石窖保温性好，利于恒温发酵  ## 窖泥：活的宝藏 石窖内壁会附着一层厚厚的窖泥，其中包含丰富的微生物群落。老酒厂的窖泥经过数十年甚至上百年的积累，菌群结构极其复杂，能够产出更丰富的风味物质。这就是为什么老酒厂的酒往往更好——窖泥本身就是不可复制的\'无形资产\'。  ## 石窖 vs 泥窖 - 石窖（酱酒）：透气、石壁发酵，产酱香 - 泥窖（浓香）：密封、泥壁发酵，产窖香 - 地缸（清香）：完全隔绝泥土，产清香  三种发酵容器，决定了三大香型的本质差异。` },
      'klg_017': { id: 'klg_017', title: `大曲的秘密：酱酒风味的主要来源`, author: `酱酒知识库`, icon: `🫙`, views: 9876, content: `大曲是以小麦为原料，经粉碎、踩制成型、自然发酵而成的糖化发酵剂，是酱酒风味的\'总设计师\'。  ## 酱酒大曲的特点 - 原料：100%优质小麦 - 制曲温度：60-65°C（所有白酒中最高） - 用曲量：与高粱比例接近1:1 - 储存时间：新曲需存放6个月以上才能使用 - 制曲季节：集中在端午时节  ## 大曲的三大作用 1. 糖化发酵剂：大曲中的微生物产生各种酶类，将淀粉→糖→酒精 2. 风味来源：大曲发酵过程中产生大量香气物质和风味前驱物 3. 原料：大曲本身也是酿酒原料，参与酒体形成  ## 高温大曲 vs 中温大曲 - 高温大曲（60-65°C）：酱酒专用，产生酱香和焦香 - 中温大曲（50-60°C）：浓香型白酒用 - 低温大曲（40-50°C）：清香型白酒用  温度越高，曲中的细菌（芽孢杆菌）越多，产生的吡嗪类化合物越多——这是酱酒\'酱香\'的科学来源。` },
      'klg_018': { id: 'klg_018', title: `从一粒粮到一滴酒：酱酒生产全过程`, author: `酱酒知识库`, icon: `🏭`, views: 16789, content: `一瓶酱酒从原料到出厂，至少需要5年时间、30多道工序、160多个工艺环节。让我们完整走一遍这个奇妙的过程。  ## 第一阶段：制曲（40天+6个月储存） 小麦粉碎→踩制成型→入仓发酵→翻仓→出仓→储存半年  ## 第二阶段：酿酒（1年） 1. 下沙：润粮→蒸粮→摊凉→加曲→堆积发酵→入窖（30天） 2. 糙沙：重复上述流程，投入剩余50%高粱 3. 1-7轮次取酒：蒸煮→摊凉→加曲→堆积→入窖→取酒（循环7次，约8个月）  ## 第三阶段：储存（3年+） 分型定级→入陶坛储存→定期盘勾  ## 第四阶段：勾调 小盘勾（小样）→大盘勾（量产）→调味  ## 第五阶段：再储存（6个月-1年） 勾调后酒体需再储存半年以上，让酒体融合稳定  ## 品质管控 在整个生产过程中，茅台酒厂对每个环节都有严格的检测标准。仅基酒就要经过100多项指标检测，确保每批次品质稳定。  耗时：制曲40天+储存6月 → 酿酒1年 → 储存3年+ → 勾调+再储存1年 = 约5.5年  这就是为什么优质酱酒如此珍贵——每一滴都凝聚着时间的价值。` },
      'klg_019': { id: 'klg_019', title: `酱酒酿造中的科技密码`, author: `酱酒知识库`, icon: `🔬`, views: 7890, content: `酱酒酿造看似传统，实则处处是科学。现代科技的介入，正在让千年工艺焕发新的生命力。  ## 微生物组学研究 - 茅台已分离鉴定1946种微生物 - 发现了\'石窖梭菌\'\'茅台梭菌\'两个全新菌种 - 通过宏基因组测序技术，解析发酵过程中菌群演替规律 - 建立了茅台酒微生物菌种资源库  ## 风味化学 - 茅台酒已查明香气成分300余种 - 其中吡嗪类、呋喃类化合物是酱香的重要来源 - 四甲基吡嗪（川芎嗪）是茅台酒中含量较高的健康因子  ## 智能酿造 - 国台酒业率先引入智能化酿造 - 智能温控发酵系统确保恒温恒湿 - 自动化上甑减少人工误差 - AI辅助勾调系统辅助调酒师决策  ## 品质溯源 - 区块链技术追踪每一瓶酒从原料到出厂的全流程 - RFID防伪标签打击假冒伪劣 - i茅台APP实现数字化直营  传统工艺是灵魂，现代科技是翅膀。两者的结合，让中国酱酒在保留传统风味的同时，实现品质的标准化和规模化。` },
      'klg_020': { id: 'klg_020', title: `酱酒与其他香型的区别：一张表看懂中国白酒`, author: `酱酒知识库`, icon: `📋`, views: 14567, content: `中国白酒按香型分为四大基础香型和八大衍生香型。了解各香型的区别，是进阶品酒的第一步。  ## 四大基础香型对比 | 项目 | 酱香型 | 浓香型 | 清香型 | 米香型 | |------|--------|--------|--------|--------| | 代表 | 茅台 | 五粮液 | 汾酒 | 桂林三花 | | 原料 | 高粱 | 多粮 | 高粱 | 大米 | | 曲种 | 高温大曲 | 中温大曲 | 低温大曲 | 小曲 | | 发酵容器 | 石窖 | 泥窖 | 地缸 | 陶缸 | | 周期 | 1年 | 45-90天 | 28天 | 7天 | | 香气特征 | 酱香、焦香 | 窖香、粮香 | 清香纯正 | 蜜香、米香 | | 口感 | 醇厚细腻 | 绵甜爽净 | 清香柔和 | 蜜甜清爽 | | 储存 | 3年+ | 1年+ | 半年+ | 3个月+ |  ## 酱香的独特优势 - 工艺最复杂，品质上限最高 - 储存时间最长，风味物质最丰富 - 空杯留香持久（24小时以上） - 适量饮用不上头、不口干  ## 为什么酱酒更贵？ 酱酒的生产成本远高于其他香型： - 出酒率低（约20%） - 周期长（5年起） - 储存成本高 - 原料要求严格` },
      'klg_021': { id: 'klg_021', title: `茅台官方品鉴四式：这才是正确的品酒方式`, author: `酱酒知识库`, icon: `👁️`, views: 16789, content: `茅台官方（e-moutai.com）公布了标准的品鉴方法——\'品鉴四式\'，这是品鉴茅台酒的正确打开方式。  ## 第一步：看（举杯齐眉，观其色） - 将酒杯举至与眉毛齐平 - 观察酒液的色泽和透明度 - 优质酱酒应呈微黄色，清澈透明无杂质 - 轻轻晃动酒杯，观察挂杯——酒液沿杯壁缓缓流下，形成\'酒泪\' - 年份越久，颜色越深，挂杯越明显  ## 第二步：闻（低头倾杯，鼻闻其香） - 将酒杯放低至胸前，缓缓靠近鼻腔 - 先远闻（杯口距离鼻子5-8cm），感受整体香气 - 再近闻（2-3cm），辨别层次：酱香→焦香→糊香→花果香 - 优质酱酒香气优雅细腻，无刺鼻酒精味  ## 第三步：尝（细品慢咽，口尝其味） - 轻啜一小口（约2-3ml） - 让酒液铺满整个舌面 - 感受酒体的醇厚、细腻、协调 - 吞咽后感受回味——好的酱酒回味悠长，可达数分钟  ## 第四步：格（融合色香味，感受风格） - 综合色、香、味的体验 - 品味酒的整体风格——是否\'酱香突出、优雅细腻、酒体醇厚、回味悠长\' - 空杯留香——饮后空杯静置，优质酱酒空杯留香可达24小时以上` },
      'klg_022': { id: 'klg_022', title: `吴晓波六步品酒法：从行家视角品鉴茅台`, author: `酱酒知识库`, icon: `🍷`, views: 12456, content: `知名财经作家、茅台爱好者吴晓波总结了一套六步品酒法，被众多酱酒爱好者奉为经典。  ## 六步法详解  ### 第一步：清水漱口 品酒前用清水漱口，清除口腔异味，让味蕾恢复\'清零\'状态。这一步常被忽视，却至关重要。  ### 第二步：观色 举杯对光，观察酒液颜色和挂杯情况。注意年份与颜色的对应关系——颜色越深通常年份越久，但也可能是添加焦糖色所致（优质酱酒不添加焦糖色）。  ### 第三步：闻香 将酒杯倾斜45°，让香气自然释放。先远闻判断香气类型（酱香/焦香/花香），再近闻辨别层次。  ### 第四步：尝味 不要急着咽下。让酒液在口中停留3-5秒，用舌尖（感受甜）、舌侧（感受酸）、舌根（感受苦）全面感知。  ### 第五步：回味 咽下后感受余味。好的酱酒回味悠长，可达数分钟；差酒回味短，甚至有苦涩感。  ### 第六步：综合判定 综合以上五步的体验，给出整体评价。不追求\'标准答案\'，品酒是非常个人化的体验。  ## 品酒礼仪 - 不要一口闷 - 不要空腹品酒 - 品酒顺序：先淡后浓，先年轻后陈年` },
      'klg_023': { id: 'klg_023', title: `酱酒年份指南：从3年到80年，不同年份的酱酒有什么不同`, author: `酱酒知识库`, icon: `📅`, views: 15678, content: `年份是影响酱酒品质和价格的最重要因素。了解不同年份酱酒的特点，是选购和收藏的基础。  ## 3-5年（新酒期） - 口感：略有辛辣感，香气较冲 - 特点：酒体尚不够协调，层次感不足 - 适饮：日常饮用，性价比高 - 代表：新出厂的飞天茅台  ## 5-10年（成熟期） - 口感：辛辣感大幅减弱，口感变绵柔 - 特点：香气开始丰富，层次感显现 - 适饮：宴请、品鉴  ## 10-20年（黄金期） - 口感：醇厚绵柔，入口即化 - 特点：酱香突出，空杯留香持久，层次丰富 - 适饮：高端宴请、重要场合 - 官方认证这是最适合品鉴的年份区间  ## 20-30年（珍品期） - 口感：极其醇厚，如同丝绸般顺滑 - 特点：香气内敛而复杂，回味可达数十分钟 - 适饮：收藏级品鉴，特殊纪念日  ## 30年以上（殿堂级） - 30年、50年、80年年份酒（1997年起推出） - 价格：30年约2万元+，50年约5万元+，80年约20万元+ - 特点：不仅是酒，更是艺术品和投资品  ## 年份酒的调配原理 年份酒不是整瓶酒都是那个年份的——而是用不同年份的基酒按比例调配，以该年份为主。例如\'15年年份酒\'是以15年基酒为主体，辅以更老的调味酒。` },
      'klg_024': { id: 'klg_024', title: `茅台酒产品体系全解析：飞天、生肖、精品、年份酒的定位与区别`, author: `酱酒知识库`, icon: `🏷️`, views: 17890, content: `茅台酒拥有完整的产品矩阵，覆盖不同价位和使用场景。了解各产品线的定位，是选购茅台的基本功。  ## 核心产品线  ### 飞天茅台（53%vol 500ml） - 定位：经典旗舰，茅台的最核心产品 - 价格：建议零售价1499元（实际市场价2500+） - 场景：日常宴请、商务接待 - 特点：酱香突出，品质稳定  ### 茅台1935 - 定位：千元价格带战略产品 - 价格：约1188元 - 场景：中高端宴请 - 特点：传承1935年历史，酱香典雅  ### 精品茅台 - 定位：飞天的升级版 - 价格：约3299元 - 场景：高端宴请、重要商务 - 特点：基酒年份更长，酒体更醇厚  ### 生肖系列 - 定位：文化收藏酒 - 价格：各年份不同，约2500-5000元 - 场景：收藏、礼品、生肖纪念 - 特点：每年一款（2026年丙午马年已集结12款），融合生肖文化与非遗工艺  ### 年份酒（15年/30年/50年/80年） - 定位：顶级收藏酒 - 价格：15年约6000元，30年约2万元+，50年约5万元+，80年约20万元+ - 场景：高端收藏、重要纪念 - 特点：以高年份基酒为主体的勾调艺术结晶  ### 茅台王子酒/迎宾酒 - 定位：大众酱香入门 - 价格：200-500元 - 场景：日常饮用 - 特点：性价比高，酱香风格明显` },
      'klg_025': { id: 'klg_025', title: `酱酒收藏指南：什么样的酱酒值得收藏？`, author: `酱酒知识库`, icon: `🏆`, views: 14567, content: `酱酒收藏已成为重要的文化和投资领域。但并非所有酱酒都值得收藏——选对标的，升值空间才会大。  ## 收藏价值四维度  ### 1. 品牌 首选茅台，其次是习酒、郎酒、国台等知名品牌。品牌是收藏价值的首要保障。  ### 2. 年份 年份越久，价值越高。15年以上为珍品，30年以上为殿堂级藏品。  ### 3. 稀缺性 - 限量版：产量有限，供需关系推高价格 - 纪念酒：特定事件纪念版（如世博会、国庆等） - 停产版本：已不再生产的旧包装版本  ### 4. 品相 - 瓶身完整无破损 - 酒标清晰完整 - 瓶盖密封良好 - 原箱原封价值远高于散瓶  ## 收藏等级（由高到低） 1. 年份酒（80年>50年>30年>15年） 2. 纪念酒/生肖酒 3. 飞天茅台（早期版本） 4. 精品茅台、茅台1935 5. 知名品牌高端线（青花郎、习酒1988等）  ## 储存要点 - 温度15-20°C，湿度60-70% - 避光保存，不可阳光直射 - 平放确保酒液浸泡瓶塞（防塞干裂） - 远离异味源  ## 市场趋势 近5年酱酒收藏市场年增长率超过20%，已成为另类投资的热门赛道。` },
      'klg_026': { id: 'klg_026', title: `酱酒与美食的搭配艺术`, author: `酱酒知识库`, icon: `🍽️`, views: 10234, content: `酱酒与美食的搭配讲究相得益彰。好的搭配能让酒和菜都发挥出最佳状态。  ## 经典搭配推荐  ### 酱酒+川菜 川菜的麻辣与酱酒的醇厚相得益彰。酱酒的回甘能中和辣味，使口感更加丰富。 - 推荐组合：回锅肉、水煮鱼、麻婆豆腐  ### 酱酒+湘菜 湘菜的咸辣与酱酒的焦香相互呼应。 - 推荐组合：剁椒鱼头、毛氏红烧肉、辣椒炒肉  ### 酱酒+粤菜 粤菜的清鲜与酱酒的酱香形成对比之美。 - 推荐组合：白切鸡、烧鹅、清蒸石斑鱼  ### 酱酒+火锅 火锅的浓烈与酱酒的醇厚最为匹配。 - 推荐：重庆火锅、潮汕牛肉火锅  ## 搭配原则 - 重口味菜肴（麻辣、红烧）配陈年酱酒 - 清淡菜肴（白肉、清蒸）配年轻酱酒 - 避免配海鲜刺身（会加重腥味）  ## 饮用温度 - 最佳温度：20-25°C - 温度过低：香气不显 - 温度过高：刺激感增强 - 建议：用手心温热酒杯（人体温度37°C适中）  ## 品酒配菜顺序 先清淡后浓郁→先年轻后陈年→先白肉后红肉` },
      'klg_027': { id: 'klg_027', title: `选购酱酒的5个黄金法则：从入门到精通`, author: `酱酒知识库`, icon: `🛒`, views: 13456, content: `市场上的酱酒品牌成百上千，价格从几十元到上万元。掌握以下5个法则，选酒不再迷茫。  ## 法则一：看工艺 首选坤沙工艺。查看产品说明或询问是否采用12987工艺。凡是标注\'传统酱香工艺\'\'大曲坤沙\'的都值得信赖。  ## 法则二：查产地 核心产区出品的酱酒品质更有保障。赤水河流域（仁怀、习水、古蔺、金沙）是酱酒的黄金产区。  ## 法则三：看原料 配料表应只有：水、高粱、小麦。不应有任何添加剂（食用酒精、香精、焦糖色等）。  ## 法则四：品口感 - 好酒：入口柔顺，不辣喉，回甘明显 - 差酒：辛辣刺喉，下咽后难受 - 空杯留香测试：饮后空杯静置，好酒留香可达24小时  ## 法则五：认品牌 - 一线品牌：茅台、习酒、郎酒 - 二线品牌：国台、钓鱼台、金沙 - 区域品牌：选择当地知名、有历史的品牌  ## 不同预算推荐 - 100-300元：碎沙工艺的口粮酒 - 300-600元：入门级坤沙酒 - 600-1000元：中端坤沙酒（茅台王子酒、习酒窖藏等） - 1000-2000元：次高端（茅台1935、青花郎等） - 2000元以上：高端（飞天茅台及以上）  ## 避坑提示 - 谨防\'扫码价999元现价99元\'的低价陷阱 - 警惕过度包装、价格虚高的小品牌 - 购买渠道：优先茅台官方渠道、i茅台APP、大型商超、品牌旗舰店` },
      'klg_028': { id: 'klg_028', title: `酱酒的健康密码：为什么说\'适量饮用酱酒有益健康\'`, author: `酱酒知识库`, icon: `💚`, views: 13567, content: `适量饮用优质酱酒对健康的影响，一直是消费者关注的话题。从科学角度来看，酱酒确实具备一些独特的健康属性。  ## 科学依据  ### 1. 长期储存降低有害物质 - 基酒需储存3年以上 - 储存过程中，甲醇、醛类等有害物质大部分挥发 - 酱酒有害物质含量明显低于其他香型  ### 2. 富含健康因子 - 四甲基吡嗪（川芎嗪）：具有活血化瘀作用 - SOD（超氧化物歧化酶）：抗氧化 - 多种有机酸：促进消化 - 酚类化合物：抗氧化、抗衰老  ### 3. 纯粮酿造 - 仅用水、高粱、小麦三种原料 - 不添加任何酒精、香精、添加剂 - 天然发酵产物，成分复杂但天然  ## \'适量\'是关键 - 每日建议：≤50ml（约1两） - 过量饮酒伤肝，无论什么酒都一样 - \'适量有益\'≠\'越多越好\'  ## 为什么有人喝酱酒不上头 - 酱酒中高级醇（杂醇油）含量低 - 储存过程中大部分杂醇油已挥发 - 酒体纯净，代谢负担小  ## 郑重提醒 未成年人禁止饮酒。孕妇、肝病患者、服药期间不宜饮酒。开车不喝酒，喝酒不开车。` },
      'klg_029': { id: 'klg_029', title: `2025年酱酒行业格局：从\'一超多强\'到\'群雄逐鹿\'`, author: `酱酒知识库`, icon: `📈`, views: 12345, content: `2025年，酱酒行业格局呈现\'一超多强\'的态势，同时新兴力量正在崛起。  ## 第一梯队：一骑绝尘的茅台 - 2025年营收：超1800亿元 - 茅台酒产量：5.2万千升 - 市值：超2万亿元，全球市值最高的酒企 - 核心产品：飞天茅台，被称为\'液体黄金\'  ## 第二梯队：习酒与郎酒 - 习酒：营收突破300亿元，稳居酱酒第二 - 郎酒：营收超200亿元，青花郎为核心大单品 - 两家合计营收超500亿元  ## 第三梯队：追赶者 - 国台酒业：营收突破100亿元，冲击上市 - 金沙酒业：华润入主后营收突破200亿元 - 钓鱼台酒业：小而精的高端路线  ## 行业趋势 - 集中度持续提升：TOP5企业占据超70%市场份额 - 次高端（300-800元价格带）增长最快 - 年轻消费者（25-35岁）占比从12%提升至28% - 电商渠道占比突破40%` },
      'klg_030': { id: 'klg_030', title: `i茅台：一瓶酒的数字化革命`, author: `酱酒知识库`, icon: `📱`, views: 9876, content: `i茅台是茅台集团推出的官方数字营销平台，自2022年5月上线以来，已经成为中国白酒行业数字化转型的标杆。  ## 核心功能 - 预约申购：飞茅申购的主渠道 - 线上商城：全品类茅台产品在线购买 - 数字藏品：茅台数字文化产品 - 防伪溯源：一瓶一码，全程可追溯  ## 业绩数据 - 2025年贡献营收超300亿元 - 注册用户突破5000万 - DAU（日活用户）超500万  ## 行业影响 i茅台的成功证明了传统白酒行业也可以数字化。它带来的变革： - 砍掉中间环节，提高毛利率 - 积累消费者数据，实现精准营销 - 防伪溯源提升消费者信任 - 降低消费者购买门槛  ## 其他品牌的跟进 - 习酒推出\'习酒荟\' - 郎酒推出\'郎酒庄园\'APP - 国台推出\'国台云店\'  数字化已成为酱酒行业的必答题，而i茅台是当之无愧的标准答案。` },
      'klg_031': { id: 'klg_031', title: `茅台的国际化之路：从巴拿马金奖到全球品牌`, author: `酱酒知识库`, icon: `🌍`, views: 8765, content: `从1915年巴拿马金奖到如今遍布全球100多个国家和地区，茅台的国际化已经走过了110年。  ## 历史里程碑 - 1915年：巴拿马万国博览会金奖 - 1950年代：开始出口苏联、东欧 - 1970年代：进入日本、东南亚市场 - 1990年代：进入欧美主流市场 - 2020年代：加速全球化布局  ## 最新数据 - 2025年出口额：42.3亿美元（+28%） - 覆盖国家：100+ - 最大市场：东南亚（+35%）、北美（+42%） - 茅台+习酒+郎酒占出口额的80%  ## 国际化策略 - 文化出海：以茅台文化为先锋，讲好中国故事 - 渠道建设：自营网点+国际经销商双轮驱动 - 产品适配：针对不同市场推出差异化产品 - 品牌传播：参与国际高端活动、赞助体育赛事  ## 挑战与机遇 随着中国文化影响力提升，茅台正在从\'华人圈品牌\'向\'全球高端烈酒品牌\'转型。这是一个漫长的过程，但趋势已经不可逆。` },
      'klg_032': { id: 'klg_032', title: `茅台酒为什么这么贵？解密\'液体黄金\'的价值密码`, author: `酱酒知识库`, icon: `💰`, views: 18765, content: `飞天茅台53度500ml，建议零售价1499元，但实际市场价长期维持在2500元以上。一瓶酒为什么这么贵，又为什么总是买不到？  ## 成本端 - 原料成本：红缨子高粱+小麦，有机种植 - 时间成本：每瓶酒从投料到出厂至少5年 - 储存成本：5年储存的仓储、资金占用 - 人工成本：30+道工序，大量手工操作 - 综合成本：每瓶酒的直接成本约300-400元  ## 需求端 - 礼品属性：茅台被视为最体面的送礼选择 - 社交属性：商务宴请的\'硬通货\' - 收藏属性：越陈越值钱，年化收益超20% - 金融属性：\'液体黄金\'，具有避险功能  ## 供需失衡 - 茅台酒年产量：约5.2万千升（约1亿瓶） - 中国中高收入群体：约4亿人 - 人均不到0.25瓶/年 - 严重的供不应求是价格高企的根本原因  ## 渠道加价 - 出厂价→一批价→二批价→零售价，层层加价 - i茅台直销渠道压缩了中间环节，但申购中签率极低  ## 品牌溢价 茅台不仅是一瓶酒，更是中国白酒文化的象征。品牌价值超过5000亿元，这本身就是巨大的溢价来源。` },
      'klg_033': { id: 'klg_033', title: `酱酒新国标解读：对消费者意味着什么`, author: `酱酒知识库`, icon: `📋`, views: 11234, content: `2026年正式实施的《酱香型白酒》新国家标准，被业内称为\'酱酒史上最严国标\'。  ## 三大核心变化  ### 1. 原料标准 - 必须使用赤水河流域产的红缨子高粱 - 这是首次以国家标准形式明确了酱酒原料的产地  ### 2. 工艺标准 - 坤沙酱酒的12987工艺被正式写入国标 - 生产周期、投料方式、蒸煮发酵次数都有明确规定  ### 3. 年份酒标准 - 增加了年份酒的标注规范 - 必须标明基酒的最低年份和占比 - 杜绝\'数字游戏\'（如标注30年实际用1滴老酒）  ## 对行业的影响 - 预计淘汰20%不合规的中小酒企 - 行业集中度进一步提升 - 优质坤沙酒获得更好的市场认可  ## 对消费者的好处 - 购买时有标准可依，不再\'盲买\' - 年份酒标注规范，杜绝造假 - 不合规产品被淘汰，市场更健康  ## 如何辨别 购买时看产品标准号：GB/T 26760（酱香型白酒国家标准）。` },
      'klg_034': { id: 'klg_034', title: `赤水河生态保护：保障酱酒产业的\'生命线\'`, author: `酱酒知识库`, icon: `🌿`, views: 8765, content: `赤水河被誉为酱酒的\'母亲河\'，其生态环境直接关系到酱酒产业的可持续发展。  ## 赤水河的独特价值 - 长江上游唯一未建水坝的一级支流 - 水质常年保持Ⅱ类标准 - 沿岸森林覆盖率55%+ - 独特的紫色砂页岩地质  ## 面临的挑战 - 酿酒产业扩张带来的用水压力 - 沿岸城镇化产生的生活污水 - 农业面源污染 - 气候变化导致的极端天气  ## 治理措施 - 仁怀市投资85亿元治理赤水河流域水环境 - 沿岸污水处理率达到95%以上 - 划定生态红线，限制污染企业 - 茅台集团每年投入数亿元用于环保  ## 酱酒企业的环保行动 - 茅台：建设零碳酒厂，推广清洁生产 - 习酒：赤水河流域生态修复项目 - 郎酒：天宝洞天然储酒，零碳排  ## 为什么环保关系到每一瓶酒 水质、空气、土壤——每一个环境因素都直接影响酱酒的品质。保护赤水河，就是保护每一瓶酱酒的品质。` },
      'klg_035': { id: 'klg_035', title: `走进茅台酒厂：全球市值最高酒企的秘密`, author: `酱酒知识库`, icon: `🏛️`, views: 16789, content: `贵州茅台酒厂是全球市值最高的酒企（市值超2万亿元），但它的起点只是茅台镇上三家普通的烧房。  ## 历史沿革 - 成义烧房（1862年）：华联辉创立，后称\'华茅\' - 荣和烧房（1879年）：王立夫等创立，后称\'王茅\' - 恒兴烧房（1929年）：周秉衡创立，后称\'赖茅\' - 1951年：三家合并为国营茅台酒厂  ## 现代化进程 - 1975年：茅台酒被定为国宴用酒 - 2001年：上交所上市（600519） - 2020年：市值突破2万亿元 - 2025年：营收突破1800亿元  ## 茅台的核心竞争力 1. 不可复制的地理环境（赤水河茅台镇） 2. 独特的12987酿造工艺 3. 70年积累的品牌资产 4. 严格的质量管理体系 5. 深厚的文化底蕴  ## 茅台的企业文化 \'爱我茅台，为国争光\'——这八个字浓缩了茅台人的精神追求。从\'一瓶酒\'到\'一个文化符号\'，茅台已经成为中国制造的世界名片。` },
      'klg_036': { id: 'klg_036', title: `中国白酒八大核心产区：一张图看懂好酒在哪里`, author: `酱酒知识库`, icon: `🗺️`, views: 11234, content: `中国白酒已形成八大核心产区格局，每个产区因地理、气候、水质的不同，孕育了风格迥异的美酒。  ## 八大产区一览  **遵义产区（酱香）** - 核心：仁怀茅台镇 - 代表：茅台、习酒、国台、珍酒 - 2026年白酒产值目标1512亿元  **宜宾产区（浓香）** - 核心：五粮液 - 代表：五粮液、叙府、永福酱酒 - 支持五粮液进军世界500强  **泸州产区（浓香）** - 代表：泸州老窖、郎酒 - 2025年酒类营收1520亿元 - 2030年目标2000亿  **宿迁产区（浓香）** - 代表：洋河、双沟 - 江苏白酒双核驱动  **吕梁产区（清香）** - 代表：汾酒 - 2025年清香品类热度显著上升  **亳州产区（浓香）** - 代表：古井贡酒 - 连续冠名中国诗词大会  **成都/德阳产区（浓香）** - 代表：水井坊、剑南春 - 四川白酒出口增长10.7%  ## 香型格局 当前呈现\'酱香热、清香暖、浓香缩\'态势。浓香仍占约50%以上份额但增长放缓，酱香以茅台为龙头持续高端化，清香以汾酒为代表快速崛起。产区正在从\'地理标签\'升级为\'流量IP\'。` },
      'klg_037': { id: 'klg_037', title: `酱酒电商全渠道解析：i茅台、抖音、私域怎么玩`, author: `酱酒知识库`, icon: `📱`, views: 9876, content: `2025年贵州白酒线上销售额达461.38亿元，线上渗透率持续提升。三大渠道正在重塑酱酒销售格局。  ## i茅台：数字化直营标杆 - 2026年5月开售时间优化调整 - 上线茅台酱香系列酒519品牌节活动 - 茅台1935（尊享）i茅台首秀超预期 - 茅台上调部分产品自营零售价格  ## 抖音：白酒新主场 - 2025年抖音酒水即时零售月GMV增长71% - 国台一季度抖音销售额增长超100% - 小酒喔抖音年销售额2亿元，即时零售订单300万单 - 抖音专项治理酒水虚假营销，习酒统一电商授权店标识  ## 全域营销时代 - 淘天、京东、抖音、美团、小红书等七大平台联合拆解白酒新战法 - 《2026中国酒业全域营销观察报告》发布 - 美团闪购推出\'白酒节\'月度专区  ## 私域运营 - 郎酒PLUS会员突破4800万 - 习酒·知交酒粉丝突破200万 - 珍酒李渡董事长吴向东亲自下场直播  私域不是可选项，而是酱酒品牌的必答题。` },
      'klg_038': { id: 'klg_038', title: `年轻人喝白酒吗？2026白酒消费趋势报告`, author: `酱酒知识库`, icon: `👥`, views: 8765, content: `白酒行业的\'年轻化\'不再是一句口号。2026年的数据表明，年轻人正在用他们的方式重新定义白酒消费。  ## 年轻人确实在喝白酒 - 即时零售渠道年轻人白酒下单率超60% - 斑马侠等新零售品牌吸引85%年轻客群 - 单店月销10万元，复购率40%  ## 低度化创新 - 中国酒类流通协会指出：酱酒须从\'金融属性\'回归\'消费属性\'，走低度化创新之路 - 五粮液\'一见倾心\'联名纯K，将白酒打造为年轻人社交潮品 - \'吒酒\'等新消费品牌以\'情绪价值\'切入年轻市场  ## 消费双轨并行 - 品质升级：高端白酒需求依然强劲 - 理性消费：\'性价比是王道\'成为行业共识 - 经济学家李迅雷建议：酒企应开发更贴近年轻人价格的新品  ## 行业预判 整体呈现\'品质升级+理性消费\'双轨并行特征。白酒品牌需要从\'品牌年轻化\'迈向\'赢得年轻人\'。` },
      'klg_039': { id: 'klg_039', title: `茅台之外选什么？国台、珍酒、金沙三大品牌横评`, author: `酱酒知识库`, icon: `⚖️`, views: 13456, content: `飞天茅台一酒难求，酱酒爱好者不妨关注这些\'第二阵营\'的好选择。  ## 国台酒业 - 定位：\'真实年份酒\' - 2025年销量增长8% - 一季度抖音销售额增长超100% - 十年品质承诺建立品牌信任 - 2026年打造\'仓店/馆联盟体\'新模式 - 价格带：300-800元  ## 珍酒（港股上市） - 定位：\'异地茅台\'历史传承 - \'大珍·珍酒\'回款突破10亿元 - 港股唯一酱酒上市公司（6979.HK） - 资本加持下全国化扩张加速 - 价格带：200-1200元  ## 金沙酒业（华润入主） - 定位：高端商务宴席 - 摘要系列定位800-1200元 - 华润啤酒123亿收购后渠道重塑 - 央企资源赋能，全国化布局加速 - 价格带：300-1200元  ## 选购建议 - 自饮口粮：国台国标酒（300-500元） - 商务宴请：金沙摘要（800-1200元） - 送礼收藏：珍酒珍十五（500-800元）` },
      'klg_040': { id: 'klg_040', title: `白酒里的中国文化：从古酒器到诗词酒令`, author: `酱酒知识库`, icon: `🏺`, views: 10234, content: `白酒不仅是饮品，更是中华文化的活化石。  ## 古酒器：凝固的历史 - 商周青铜爵：最早的酒器，也是礼器 - 汉代漆耳杯：\'曲水流觞\'的雅趣 - 唐宋瓷执壶：酒器从礼器走向生活 - 明清温酒壶：\'煮酒论英雄\'的浪漫  ## 酒令文化 - 投壶：先秦士大夫的饮酒礼仪 - 行酒令：唐诗宋词中的飞花令 - 猜拳：民间最普及的酒桌游戏 - 现代：从\'专家评酒\'走向\'消费者评酒\'  ## 酒与诗词 - 曹操：\'对酒当歌，人生几何\' - 李白：\'人生得意须尽欢，莫使金樽空对月\' - 苏轼：\'明月几时有，把酒问青天\' - 五粮液连续四届参与中国诗词大会 - 古井贡酒将\'中国酿\'植入诗词IP  ## 当代酒文化 - 五粮液投16.14亿建设501古窖池中国白酒文化圣地 - 酣客提出\'重新发明白酒、再造白酒文化\' - 从\'酒文化\'转向\'消费文化\'，从历史叙事转向生活方式叙事  白酒文化正在从讲\'老故事\'转向创造\'新体验\'。` },
      'klg_041': { id: 'klg_041', title: `2026酱酒行业最新动态：调整期中的机会与挑战`, author: `酱酒知识库`, icon: `📊`, views: 15678, content: `酱酒行业经历了2025年的深度调整，2026年正迎来企稳回暖的关键时期。  ## 调整期数据 - 中国酒业协会理事长宋书玉指出：2025年酿酒产业量、价、利同步收缩 - 2026年3月酒类居民消费价格下降2.8% - 但4月烟酒类零售额同比增长11.7% - 茅台等头部酒企批价企稳，释放回暖信号  ## 区域政策加码 - 遵义2026年力争白酒产值达1512亿元 - 古蔺明确做大做强酱酒首位产业 - 仁怀酱酒加速全球化，\'美酒献全球\'行至香港  ## 品牌动态 - 茅台集团连续十年参展济南中酒展 - 茅台保健酒业锚定\'大众酱香+酱香露酒\'双赛道 - 红花郎获\'中国宴席市场连续三年酱酒销量第一\' - 珍酒\'大珍·珍酒\'回款破10亿  ## 行业趋势 - 从\'金融属性\'回归\'消费属性\' - 性价比成为王道 - 连锁零售进入最好时代 - 酱酒从\'核心产区\'向\'全球品牌\'升级  调整不是衰退，是洗牌。能穿越周期的品牌，将在下一轮增长中收获最大红利。` },
      'klg_042': { id: 'klg_042', title: `仁怀酱酒产业全景：506家获证酒厂、占全国4.6%的产能密码`, author: `酱酒知识库`, icon: `🏭`, views: 18900, content: `仁怀市是中国酱酒的核心产区，其产业规模远超一般人想象。  ## 506家获证酒厂 根据国家食品药品监督管理总局公开数据，截止2019年2月11日，仁怀市共有食品生产许可(SC)获证酒厂506家。  ## 在全国的地位 - 全国酒类生产许可证：10,862张 - 贵州省：751张 - 遵义市：574张 - **仁怀市：506张，占贵州67%、占遵义88%、占全国4.6%**  对比其他白酒产区：四川宜宾109张，四川泸州293张。仁怀一个县级市的获证酒厂数量，远超宜宾和泸州两个地级市之和。  ## SC许可证的价值 食品生产许可证是白酒企业的\'准生证\'。由于国家发改委2011年将白酒列入限制产业、禁止新建生产线，SC许可证成为稀缺资源。 - **2012年，仁怀一张白酒生产许可证转让价高达668万元** - SC编码规则：SC+14位数字。如茅台：SC11552038220099（115=酒类，52=贵州，03=遵义，82=仁怀）  ## 对消费者的意义 SC编号实现了食品的全程追溯。消费者可通过编号查询：原料从哪里来、在哪里加工、何时产出。该编号与企业一一对应，终身不变。  ## 产业格局 506家获证酒厂中，既有茅台这样的巨无霸（年产5.2万吨），也有大量年产几百到几千吨的中小企业。这些企业共同构成了仁怀酱酒产业的完整生态。  *来源：国家食品药品监督管理总局公开数据、山荣说酒公众号*` },
      'klg_043': { id: 'klg_043', title: `抖音金黄桶装酱酒是真老酒吗？新国标说清楚了`, author: `酱酒知识库`, icon: `🛢️`, views: 5800, content: `最近很多酒友私信：抖音上透明塑料桶装的酱香酒，颜色金黄透亮，看着像陈年老酒，这种黄是自然的，还是加了东西？  今天结合最新国标GB/T 10781.4-2024，把桶装酱酒颜色猫腻、塑料存酒风险一次性讲透。  ## 一、新国标：正宗酱香酒该是什么颜色？  新国标GB/T 10781.4-2024（2025-06-01实施）明确： - 酱香型白酒：清澈、透明、无色或微黄，无沉淀、无悬浮物 - 严禁添加焦糖色、合成色素、香精、甜味剂 - 不得添加食用酒精及非发酵呈香呈味物质  微黄来自长期储存中天然联酮类物质，随年份缓慢加深： - 3-5年：极淡微黄 - 10年+：略深，但依然清亮通透、不厚重、不发闷  **真老酒是\'清浅微黄\'，不是\'深金黄、浓茶黄\'。** 抖音桶装酒那种金黄浓郁、死板不自然，大概率是新酒+人工色素，用颜色冒充年份。  ## 二、塑料桶装酒：不止颜色坑，更要命是安全隐患  酱香荟不建议买、更不建议长期用塑料桶装酱酒，尤其夏天放车里、暴晒：  **1）高温必出塑化剂，伤身体** 普通塑料桶耐热差，暴晒/高温→塑化剂析出，溶进酒里，长期饮用危害很大。  **2）酒体变味、发臭，毁掉酱香** 酱酒活性物质多，长期接触塑料会：腐蚀桶壁、带入塑胶臭、杂味；破坏酱香层次，醇厚变寡淡、纯正变杂味。  存酒正确做法：陶坛、玻璃、食品级不锈钢，避光、阴凉、密封。  ## 三、新国标重点：买酱酒认准这3点  1. **标准号**：2025-06-01后认准GB/T 10781.4-2024；旧国标GB/T 26760-2011同期废止 2. **工艺标注**：优先选酱香型白酒（大曲），传统12987、高温大曲、固态发酵；\'其他\'为麸曲/混合曲，品质门槛更低 3. **色泽判断**：清澈微黄、通透干净、香气纯正、空杯留香持久；颜色过黄、香气单薄、入口辛辣、有塑胶味→直接pass  ## 四、最后提醒  - 颜色≠年份：金黄多是调色，清浅微黄才是真年份本色 - 坚决不用塑料桶存酒，尤其高温、暴晒环境 - 新国标落地后，无添加、纯固态、工艺透明才是趋势  喝酱酒，喝的是纯正、健康、真实年份。懂标准、辨颜色、选对容器，才能喝明白每一口酱香。` },
      'klg_044': { id: 'klg_044', title: `1399元的拼多多茅台，凭啥敢卖？深度拆解百亿补贴的茅台玩法`, author: `酱酒知识库`, icon: `🛒`, views: 7200, content: `在中国的酒水江湖里，茅台的价格一直像\'理财产品\'一样坚挺。但如果你经常逛拼多多，一定会被那个常年挂在首页的\'1399元茅台三人团\'震撼到。  ## 为什么拼多多敢卖1399元？  **1. 百亿补贴是真补贴** 拼多多用百亿补贴真金白银地贴钱引流，茅台作为\'引流爆品\'，平台愿意每瓶亏几百元。这不是卖酒，是在买用户。  **2. 正品保障机制** 拼多多的茅台供应商经过严格筛选，渠道可溯源。虽然价格低，但并不代表一定是假酒。平台通过先验货后发货、假一赔十等机制保障。  **3. 限时限量控制风险** 1399元不是无限量供应，而是定时定量抢购。限量的逻辑是控制补贴成本，同时制造稀缺感和话题性。  ## 消费者该不该买？  - 如果买到正品，1399元确实远低于市场价（飞天市场价约2500元），是真划算 - 收到货后建议：扫描瓶盖NFC芯片、检查瓶盖防伪标识、通过i茅台APP验证 - 有疑虑的消费者建议选择：i茅台APP申购（1499元）、茅台官方旗舰店、大型商超渠道  ## 对行业的启示 拼多多的1399元茅台，本质上是用互联网流量的逻辑在做酒。它证明了：在流量面前，茅台1499元的指导价也只是个参考价。` },
      'klg_045': { id: 'klg_045', title: `段永平最新发声：茅台供不应求将持续三年以上`, author: `酱酒知识库`, icon: `💰`, views: 8500, content: `知名投资人段永平在雪球平台持续与网友互动，分享了自己对茅台的最新看法。  ## 段永平的核心观点  **供不应求将持续三年或更长** 段永平认为，茅台的供需矛盾短期内难以解决。茅台酒的年产量约5.2万千升，而中国有数亿中高收入群体，供需缺口巨大。他估计，茅台供不应求的情况会持续三年或者更长。  **存酒可能比买茅台股票更划算？** 在互动中，段永平提到存酒和买股票两种投资方式的对比。茅台酒本身具备\'越陈越香、越陈越值钱\'的属性，优质酱酒年化增值率可达15-20%，而茅台股票近年来也保持了稳定的分红和增长。  ## 其他投资大佬怎么看？  林园（知名投资人）：茅台是\'全球最好的生意\'，50%+的毛利率、供不应求的格局、不可复制的品牌护城河。  但斌（东方港湾）：长期看好茅台，认为茅台是中国消费品的\'皇冠明珠\'。  ## 对普通消费者的启示  1. 飞天茅台当前市场价约2500元，建议零售价1499元，差价的本质是供需失衡 2. 对于自饮或送礼需求，建议通过i茅台申购或官方渠道购买 3. 对于投资需求，年份酒（15年/30年）长期增值潜力更大` },
      'klg_046': { id: 'klg_046', title: `仁怀酱香酒酒业：行业调整中的稳产提质样本`, author: `酱酒知识库`, icon: `🏭`, views: 4500, content: `近日，走进仁怀酱香酒庄生产车间，酱香浓郁、暖意融融，工人正精心酿制酱香白酒二轮次基酒，拌料、上甑、摘酒等传统工序有序开展。依托仁怀酱香酒庄等生产基地，仁怀市酱香酒酒业有限公司年产能稳定在8000吨。  ## 行业调整周期中的\'稳\'  在行业调整周期中\'稳\'正是这家国有控股酒企的发展底气。仁怀酱香酒酒业近年来紧抓数字化转型机遇，在线上营销方面不断突破。同时，企业在稳产提质方面持续发力，确保每一批基酒都达到高标准。  ## 仁怀产区整体态势  作为中国酱酒核心产区，仁怀市在2026年力争白酒产值达1512亿元。赤水河流域的保护和治理也在持续推进，仁怀市已投资85亿元用于赤水河流域水环境治理，沿岸污水处理率达95%以上。  产区内的500多家获证酒厂，正在从\'规模扩张\'转向\'品质提升\'的发展阶段。` },
      'klg_047': { id: 'klg_047', title: `春糖会现场直击：茅台展位火爆，排长队买1L装飞天`, author: `酱酒知识库`, icon: `🎪`, views: 6300, content: `3月26日，第114届春季糖酒会在成都开幕。在酒类展区所在的世纪城新国际会展中心，贵州茅台展位成为全场最受关注的焦点之一。  ## 茅台展位火爆盛况  今年茅台展位位于3号馆，现场人气火爆，排队买1L装飞天的消费者排成长龙。在行业分化加剧的背景下，茅台作为头部企业的市场表现和品牌号召力，在春糖会现场得到了直观印证。  ## 春糖会释放的信号  1. **头部品牌虹吸效应**：茅台、五粮液等头部品牌展位人气明显高于其他品牌 2. **酱酒依旧热度不减**：酱酒品类展区整体人气旺盛 3. **消费升级趋势持续**：高端白酒需求依然强劲  ## 相关产业数据  2025年贵州白酒线上销售额达461.38亿元，线上渗透率持续提升。i茅台APP、抖音直播、私域运营已成为酱酒营销的三大引擎。` },
      'klg_048': { id: 'klg_048', title: `白酒已死，再无超级大单品？——春糖会后的行业思考`, author: `酱酒知识库`, icon: `💡`, views: 9100, content: `这次参加糖酒会，和不少行业朋友深度交流后，一个直观感受愈发清晰：白酒行业早已大局已定，所谓\'白酒新机遇\'基本已死。  ## 核心观点  **超级大单品时代落幕** 如果当下还有人宣称要打造白酒超级大单品，基本都是忽悠。白酒行业的品牌格局已经固化，头部品牌牢牢占据心智高地，新品牌几乎没有突围空间。  **新品牌出路在哪？** 虽然\'白酒已死\'的说法有些绝对，但传统白酒新品牌确实很难突围。剩下的机会在于： 1. 细分赛道——比如果酒、配制酒、低度酒 2. 区域深耕——在本地市场做深做透 3. 私域运营——用小而美的圈子经营忠实用户  ## 对酱酒行业的启示  酱酒作为白酒品类中增长最快的细分市场，同样面临着品牌集中化的趋势。茅台、习酒、郎酒三大品牌占据了酱酒市场的大部分份额，但中小品牌仍有机会通过差异化定位和私域运营找到自己的生存空间。` },
      'klg_049': { id: 'klg_049', title: `茅台代总经理王莉回应：茅台是否再次提价？`, author: `酱酒知识库`, icon: `🎤`, views: 0, content: `茅台代总经理王莉在2025年度及2026年第一季度业绩说明会上，回应了多个市场关注的热点问题。  ## 关于提价  王莉表示：茅台酒的定价遵循市场规律，公司会综合考量市场供需、品牌价值、消费者接受度等因素，审慎决策。目前没有明确的提价时间表，但茅台的价格体系始终以市场为导向。  ## 关于代售模式  茅台正在研究寄售模式。代售模式的落地，是茅台渠道创新的重要一步。通过代售模式，茅台可以更直接地触达消费者，减少中间环节，提升渠道效率。  ## 系列酒战略定位  茅台系列酒（茅台王子酒、迎宾酒等）的战略定位是：在大众酱香价格带建立竞争优势，成为酱酒消费的入门首选。王莉指出，系列酒与飞天茅台形成差异化互补，共同构建茅台完整的产品矩阵。  ## 海外市场  茅台正加速全球化布局。2025年茅台出口额达42.3亿美元，同比增长28%，覆盖100多个国家和地区。东南亚和北美是增长最快的两大市场。  ## 业绩数据  2025年茅台营收超1800亿元，茅台酒产量5.2万千升，市值超2万亿元。2026年第一季度业绩表现稳健。` },
      'klg_050': { id: 'klg_050', title: `飞天连涨！茅台5月行情全线上涨，市场释放回暖信号`, author: `酱酒知识库`, icon: `📈`, views: 0, content: `2026年5月中旬，茅台酒行情呈现全线上涨态势。飞天茅台原箱从月初的1620元左右涨至1650元上方，散瓶从1520元涨至1550元。这轮上涨被市场解读为行业回暖信号。  ## 各品种行情走势  | 品种 | 月初价 | 5月12日 | 涨跌 | |------|--------|---------|------| | 26年飞天原箱 | 1620 | 1650+ | ↑ | | 26年飞天散瓶 | 1520 | 1550 | ↑ | | 精品茅台 | 3200 | 3250 | ↑ | | 茅台1935 | 1150 | 1180 | ↑ | | 陈年茅台(15) | 4320 | 4350 | → |  ## 上涨原因分析  1. **旺季预期**：端午临近，礼品和宴席需求增加 2. **渠道补货**：前期库存消化后，渠道开始补货 3. **信心恢复**：行业调整期后，市场对头部品牌的信心回升 4. **政策支持**：遵义产区政策加码，提振市场信心  ## 对消费者的建议  - 自饮需求：当前价格仍处合理区间，可入手 - 送礼需求：建议提前购买，旺季可能进一步上涨 - 收藏需求：关注精品茅台和年份酒，长期增值潜力更大` },
      'klg_051': { id: 'klg_051', title: `段永平：茅台年销量1亿瓶也远未饱和`, author: `酱酒知识库`, icon: `💬`, views: 0, content: `知名投资人段永平在雪球平台上再次分享了他对茅台的看法，其最新言论引发了市场和投资者的广泛讨论。  ## 核心观点  段永平认为：茅台的需求是巨大的，年销量1亿瓶也远未饱和，茅台酒的供需矛盾长期存在。  ## 论证逻辑  1. **消费群体庞大**：中国有4亿中高收入群体，假设每人每年消费1瓶飞天茅台，就是4亿瓶的需求 2. **产能天花板**：茅台酒年产量约5.2万千升，约合1亿瓶，即使全部用于飞天也远不能满足需求 3. **品牌不可复制**：茅台是中国消费品的皇冠明珠，品牌护城河极深 4. **消费升级趋势**：随着收入增长，更多消费者有能力购买茅台  ## 市场反应  段永平每次发声都会引发茅台股价和批价的短期波动。此前他预测茅台供不应求将持续三年以上的言论，已被市场验证。  ## 对投资者的启示  段永平连续多年持有茅台股票，被市场视为\'茅台最坚定的拥趸\'。他的观点代表了价值投资派对中国消费龙头的长期看好。` },
      'klg_052': { id: 'klg_052', title: `茅台全面向C端：三场奔赴，年轻、在地与劳动`, author: `酱酒知识库`, icon: `🔄`, views: 0, content: `茅台正在经历一场深刻的战略转型——从传统的\'渠道商模式\'转向\'消费者直营模式\'（全面向C端）。  ## 三场奔赴  **第一场：奔赴年轻** - i茅台APP注册用户突破5000万，年轻用户占比持续提升 - 茅台冰淇淋、酱香拿铁等年轻化产品探索 - 2026年，年轻人即时零售渠道白酒下单率超60% - 茅台数字化营销正在重新定义白酒与年轻人的关系  **第二场：奔赴在地** - 茅台文化与各地在地文化深度融合 - 茅台1935·寻道中国节气之旅走进长沙等城市 - 通过在地化运营，让茅台品牌更有温度和亲和力  **第三场：奔赴劳动** - 致敬劳动者，强调茅台酒是劳动者智慧的结晶 - 厚德大讲堂等企业文化活动 - 茅台工匠精神的传播与传承  ## 战略意义  茅台全面向C端的转型，不仅是渠道变革，更是品牌理念的升级。从\'卖酒\'到\'经营用户\'，通过数字化手段和内容运营，与消费者建立更深层次的情感连接。` },
      'klg_053': { id: 'klg_053', title: `江浙沪茅台市场工作会：一季度执行率已达全年1/3`, author: `酱酒知识库`, icon: `🗺️`, views: 0, content: `2026年江浙沪省区茅台酒市场工作会在上海召开，会议披露了核心市场的运营数据。  ## 核心数据  江浙沪作为茅台最重要的核心市场之一，一季度执行率已达到全年计划的1/3。这意味着在全年时间过去1/4时，江浙沪市场已完成全年1/3的销售目标，进度超出预期。  ## 市场策略  会议强调\'同心聚力 向C而行\'，核心策略包括： 1. **渠道优化**：从渠道商模式向消费者直营模式转型 2. **精准营销**：针对不同消费群体制定差异化营销方案 3. **服务升级**：提升消费者体验，强化品牌忠诚度  ## 对品牌的启示  江浙沪是茅台在全国的\'标杆市场\'，这里的运营经验和数据，将被复制到全国其他市场。作为高端消费的代表区域，江浙沪的表现直接影响茅台在全国的品牌定位和价格体系。` },
      'klg_054': { id: 'klg_054', title: `警惕坤沙伪概念：大曲坤沙是行业营销话术，根本不是官方术语`, author: `酱酒知识库`, icon: `⚠️`, views: 0, content: `酒水行业充斥着不少营销伪概念。就像大家常挂在嘴边的\'大曲坤沙\'，其实在行业权威典籍，比如沈怡方老师主编的《白酒生产技术全书》里，根本没有大曲坤沙、坤沙这类说法，正规教材里只有大曲酱香这个标准定义。  ## 头部酒企也不标\'坤沙\'  就连茅台、习酒这些头部酒企，在官方正规资料里，也从不标注自己是大曲坤沙、大曲碎沙。说白了，大曲坤沙本质就是市场炒出来的伪概念。  ## 精酿同样无国标  还有最近热度很高的\'精酿\'，目前同样没有统一的行业国标。之所以市面上精酿遍地开花、乱象丛生，一方面是有消费需求，另一方面更是门槛模糊、标准缺失，导致行业良莠不齐、以次充好泛滥。  ## 伪概念的危害  但凡头部大厂还没有牵头建立统一标准，这个概念就永远是模糊化的，谁都可以蹭、谁都可以用，最后必然陷入劣币驱逐良币的局面。  ## 对消费者的启示  1. **不要迷信\'坤沙\'标签**：很多小酒厂标榜\'纯坤沙\'，但消费者无法验证 2. **认准正规标准**：酱酒看GB/T 26760（旧）或GB/T 10781.4-2024（新国标） 3. **喝品质而不是喝概念**：真正的品质体现在口感、香气和空杯留香上，而不是营销术语 4. **头部品牌更可靠**：茅台、习酒、郎酒等大厂的品质管控更规范` },
      'klg_055': { id: 'klg_055', title: `人民日报看茅台：市场化发展与社会责任同频共振`, author: `酱酒知识库`, icon: `📰`, views: 0, content: `5月11日，《人民日报》刊发报道，聚焦贵州茅台在市场化改革与社会责任领域的协同实践。  ## 核心要点  **以品质为基，筑牢品牌生命线** 茅台坚守茅台酒酿制技艺这一国家级非物质文化遗产，依托数字技术构建全链条质量溯源体系，实现原料、酿造、储存、灌装、销售全程可查。  **优化产品供给，精准对接消费需求** 茅台进一步明晰产品定位，打造结构清晰、定位精准的产品体系，让产品成为承载匠心、文化与消费价值的关键载体。  **升级渠道服务，重构线上线下融合消费通路** 线上做强i茅台数字营销平台主阵地，优化申购流程，一季度新增用户近1400万；线下加快终端体验店布局，打造集品鉴、展示、侍酒服务于一体的终端阵地。  **深化产业协同，全链赋能构建新生态** - 坚守赤水河生态保护底线 - 自2012年启动公益助学活动以来，累计捐赠14亿余元 - 带动超12万户农户增收约16.4亿元 - 公益投入超100亿元  ## 启示  人民日报的报道代表官方对茅台市场化改革和社会责任实践的认可。对消费者而言，这意味着茅台品牌的长期稳定性有制度保障。` },
      'klg_056': { id: 'klg_056', title: `茅台董事长陈华莫干山演讲：与时代对话，焕新民族品牌生命力`, author: `酱酒知识库`, icon: `🎯`, views: 0, content: `5月10日，2026世界品牌莫干山大会在浙江德清开幕。茅台集团党委书记、董事长陈华以\'与时代对话，焕新民族品牌生命力\'为题发表演讲。  ## 四大核心维度  **一、产品价值属性更多元——满足消费新需求** 品牌价值最终靠产品来承载和彰显。在消费者更愿意为\'懂我\'买单、为\'悦己\'付费的当下，只有以\'用户视角\'重构产品逻辑，才能精准适配消费新趋势。 - 推出生肖、飞天文化系列 - \'一瓶一日期\'五星茅台酒等个性化产品 - 以需求驱动创新优质供给  **二、创新驱动效能更突显——培育发展新动能** 茅台持续推动\'经验酿造\'向\'科学酿造\'精进： - 从物系、菌系、酶系等微生物层面解析酿造机理 - 以i茅台为核心构建线上线下融合的营销体系 - 深入推进全面向C市场化转型  **三、文化表达方式更丰富——凝聚品牌认同** - 将文化基因融入品牌叙事与产品设计 - 打造茅台酒节、红缨子高粱丰收季等文化IP - 拓展\'卖酒向卖生活方式转变\' - 坚持\'文化先行\'拓展国际市场  **四、责任时代意义更彰显——创造共享价值** - 累计投入超30亿元建设环保基础设施 - 投入超4亿元保护赤水河流域生态 - 带动850万人次农户稳定增收 - 公益投入超100亿元，惠及26万学子  ## 战略意义  陈华的演讲代表了茅台未来五年的战略方向：品质为根、科技赋能、文化为魂、责任为基。这也是整个酱酒行业的风向标。` },
      'klg_057': { id: 'klg_057', title: `茅台1935·寻道中国第四季走进长沙：顺天应时，共赴山河`, author: `酱酒知识库`, icon: `🏮`, views: 0, content: `5月8日，\'茅台1935·寻道中国\'（第四季）节气之旅第二站走进\'星城\'长沙。活动循着二十四节气的脉络，以\'顺天应时，共赴山河\'为主题。  ## 活动亮点  **岳麓书院的文脉传承** 嘉宾们穿行于古朴的庭院与碑廊之间，驻足于\'实事求是\'的匾额之下，从千年学府的悠悠文脉中，感悟湖湘学派\'经世致用\'的严谨治学之道。  **恰同学少年广场的豪情** 面对青年毛泽东雕像，迎着湘江吹来的浩荡清风，重温\'指点江山，激扬文字\'的豪情壮志。  ## 王莉致辞三大维度  茅台集团总经理王莉以《顺天应时而作 循道致远而行》为题分享：  **1. 寻\'顺天应时\'之道** 二十四节气是中华民族特有的\'时钟\'。茅台始终恪守\'端午制曲、重阳下沙\'的古训，将质量是生命之魂的信仰融入四时劳作。  **2. 悟\'生生不息\'之道** 长沙既承载楚汉风华与湖湘精神，又跃动着\'敢为人先\'的时代脉搏。茅台致力于依托科学解析夯实根基，通过规范化、标准化运行贯通技术与技艺。  **3. 践\'万家共享\'之道** 茅台坚持以消费者为中心，全面推进营销市场化转型，把消费者的真实需求与品牌价值深度融合。  ## 品牌意义  茅台1935·寻道中国已持续四季，不仅是一场品牌活动，更是茅台深度挖掘中国节气文化与在地文化的重要载体。通过在全国各地的行走，茅台将酱酒文化与各地人文精神连接，让品牌更有温度和厚度。` },
      'klg_058': { id: 'klg_058', title: `酒企"分红+回购+增持"三板斧：护盘还是无奈之举？`, author: `国酒财经`, icon: `📊`, views: 8920, content: `2026年5月，白酒龙头密集推出股东回报方案，市场震动。五粮液一纸公告：分红200亿+回购80-100亿+控股股东增持30-50亿，合计310-350亿真金白银。茅台同期披露回购进展：累计回购108.33万股，支付15.21亿元。  ## 五粮液的350亿组合拳  **第一刀：分红** 2025年中期已分100亿，年度分红再加100亿，全年不低于200亿。2024-2026三年累计分红不低于600亿。这不是回馈，是明码标价告诉市场：账上有钱，而且愿意拿出来。  **第二刀：回购** 80-100亿，全部用于注销减资。这是五粮液上市27年以来头一回搞注销式回购。五粮液在公告里用了\'积极响应监管号召\'这样的官方措辞，但业内明白——不是表态，是被逼到了墙角才亮出的底牌。  **第三刀：增持** 控股股东五粮液集团出手30-50亿，6个月内完成。\'亲爹\'都下场了，信号是给二级市场看的。  ## 护盘的尴尬：打的是空气  一位私募基金经理说了一句糙话：\'茅台们现在干的，叫拿自己的钱买自己的脸。\'  白酒行业当前的核心矛盾，不是估值便宜不便宜，而是——产品卖不动，批价稳不住，渠道信心在崩塌。分红、回购、增持，能解决其中任何一个吗？  - 分红回购护的是股价，但渠道的真实处境市场心知肚明 - 五粮液喊了两年\'主动调整\'，批价倒挂仍是常态 - 飞天茅台散瓶批发价在2025年末跌破1499元官方指导价 - 茅台15.21亿回购砸进去，市值依然在蒸发  ## 渠道库存：真正的堰塞湖  业内观察者指出：350亿的护盘资金，砸的是流动性，救的是估值，但渠道库存这座堰塞湖还在往上涨。护盘可以买来喘息时间，但买不来根本性的市场修复。  ## 对行业的三点启示  1. **护盘是面子，救渠道才是里子**：市场的信心不是靠公告里的词堆出来的，是靠一瓶一瓶的酒被真实喝掉的 2. **回购救不了趋势，只能缓一缓节奏**：当\'硬通货\'神话松动，回购这点体量根本不够填市场的恐慌 3. **管理层需要走出去**：分红、回购、增持都是坐在办公室里就能完成的动作——它们展示的是财务能力，不是市场能力  ## 五粮液 vs 茅台：两种护盘逻辑  - 五粮液：27年来首次注销式回购，350亿规模史无前例，赌的是\'用钱买信心\' - 茅台：小额持续回购，更显从容，但飞天批价跌破官价同样是上市以来首次  两个龙头，两套组合拳，砸出来的资金总量轻松超过400亿。但白酒行业的周期底部，最需要的不是财务手段，而是渠道疏通和消费信心的实质恢复。  *参考：国酒财经公众号、五粮液公告、茅台公告*` },
      'klg_059': { id: 'klg_059', title: `i茅台四周年：一杯酒、一座桥、一个新生态`, author: `酒业家`, icon: `📱`, views: 9520, content: `5月19日，i茅台数字营销平台迎来上线四周年。这个曾经被视为行业试水的数字化平台，如今已成长为拥有超7000万累计用户的超级入口。  ## 四年进化之路  i茅台于2022年5月19日正式上线。四年间，平台经历了三次重大迭代： - **1.0阶段（2022-2023）**：作为茅台官方申购渠道，主打生肖酒、珍品茅台等非标产品的公平申购 - **2.0阶段（2024-2025）**：拓展到品牌文化传播、消费者互动，推出节气文化、茅台知识等内容运营 - **3.0阶段（2026）**：今年1月飞天茅台登陆i茅台，标志着平台从\'增量渠道\'升级为\'全品类核心渠道\'  ## 2026年核心数据  飞天茅台登陆i茅台后，平台迎来爆发式增长： - 单月新增用户628万 - 月活超1531万 - 成交订单超212万笔 - 累计用户突破7000万  ## 四周年品牌节亮点  - 购酒时间从上午9点调整至晚间8点，提货延长至晚8点 - 集中上新：陈年茅台(30)、50ml×5套装、200ml飞天、丙午马年珍享版等限量投放 - 让\'白天上班、晚上喝酒\'的消费时间精准适配  ## 生态枢纽定位  i茅台的升级方向是构建\'消费者、平台、渠道\'三方共赢的渠道协同枢纽： - **消费者端**：正品保障、价格透明、购酒便捷 - **平台端**：精准用户画像、数字营销数据分析、品牌文化输出 - **渠道端**：线上线下融合、经销商数字化赋能、库存透明管理  ## 行业启示  i茅台的成功不只是茅台的胜利，它为整个白酒行业的数字化转型提供了样板： 1. 直销渠道可以与传统经销渠道共存共赢 2. 数字化不是简单的电商化，而是品牌运营、用户运营的全面升级 3. 文化内容+数字工具的结合，是白酒品牌年轻化的有效路径  *参考：酒业家报道*` },
      'klg_060': { id: 'klg_060', title: `茅台摸到拐点：非标全线上调，白酒回暖信号已现`, author: `21世纪经济报道`, icon: `📈`, views: 8750, content: `2026年5月，茅台迎来关键拐点。5月16日i茅台发布调价公告，非标茅台酒全线调价，市场为之震动。  ## 调价详情  四款自营产品价格上调： - 陈年茅台(15)：上调约200元 - 精品茅台：上调约100元 - 公斤茅台：上调约80元 - 马年生肖酒珍享版：上调约60元  茅台官方称此为\'随行就市\'的动态调价机制，标志着定价策略从行政化向市场化转型。  ## 企稳回升信号  此前白酒行业经历了长达两年的调整期： - 飞天茅台散瓶批发价一度跌破1499元官方指导价 - 渠道库存高企，经销商信心不足 - 五粮液、习酒等品牌批价倒挂成为常态  3月底飞天茅台提价是第一个信号，5月非标全线调价是第二个信号。茅台酒全系列产品价格企稳回升，意味着行业最艰难的时刻可能已经过去。  ## 白酒出口五年翻倍  另一个积极信号来自国际市场： - 2020年白酒出口额：4.60亿美元 - 2025年白酒出口额：8.92亿美元 - 五年增长近一倍 - 平均单价从32.39美元/升上涨至53.57美元/升  ## 国际化新动作  - 茅台将在TFWA亚太免税博览会上推出低度茅台酒 - 人头马君度集团大中华区CEO率队到访茅台，探讨合作 - 白酒出海从\'华人圈\'向\'国际主流市场\'试探  ## 对行业的启示  1. **茅台的价格是行业温度计**：茅台全系列企稳，意味着高端白酒需求端真正回暖 2. **市场化定价取代行政定价**：\'随行就市\'机制让价格更能反映真实供需 3. **出口是中国白酒的未来增量**：国内市场增速放缓，国际化是必由之路 4. **低度化是出海关键**：为适应国际消费习惯，低度茅台酒的推出意义重大  *参考：21世纪经济报道*` },
      'klg_061': { id: 'klg_061', title: `赖世家：从"白酒+"到"AI+"，以数智化重构酱酒消费新场景`, author: `新华网`, icon: `🤖`, views: 6230, content: `在2026世界品牌莫干山大会上，贵州赖世家酒业提出了一个大胆的概念——从\'白酒+\'转向\'AI+\'，以人工智能技术深度赋能传统酱酒产业。  ## 四大维度重构消费场景  **品质透明：人人皆可品鉴** AI风味分析系统可精准拆解酒体中的微量物质，将过去只能凭经验感知的香气、口感、回味，转化为可视化的数据图谱。消费者扫码即可了解一瓶酒的\'风味档案\'。  **沉浸体验：云端酿造之旅** 针对年轻消费群体，搭建云端沉浸式酿造体验场景。用户可以在手机或VR设备上\'走进\'茅台镇的酿造车间，体验制曲、下沙、发酵、蒸馏的全过程。  **个性消费：AI定制酒体** 依托AI口味偏好算法，用户通过简单的口味测试后，系统可推荐或定制个性化酒体配方。\'你喜欢的酱酒\'不再是一句口号，而是可以被技术实现的产品逻辑。  **文化亲民：数字化传承** 以数字化、趣味化方式让传统酱酒文化适配新时代消费需求。将\'12987\'工艺、节气文化等深厚内容，转化为短视频、互动游戏等轻量化形式。  ## 从概念到落地  赖世家不是空谈概念。这家赖茅传人创办的企业，近年来在数字化方面持续投入： - 建立了行业领先的数字化酿造管理系统 - 实现了从原料到成品的全链条溯源 - 推出了行业首个AI品鉴小程序  ## 行业意义  酱酒行业的数智化转型已是大势所趋： - 茅台i茅台：渠道数字化标杆 - 赖世家AI+：消费体验数字化探索 - 习酒、郎酒等也在跟进数字化建设  AI不是要替代传统工匠的\'手艺\'，而是让\'手艺\'背后的科学原理更加透明、可传承。这对酱酒行业的品质提升和文化传播具有深远意义。  *参考：新华网报道*` },
      'klg_062': { id: 'klg_062', title: `仁怀酱酒千亿产值背后的"六链协同"：从产区优势到经济圈融合`, author: `糖酒快讯`, icon: `🔗`, views: 5680, content: `2025年仁怀市规上白酒总产值达1177.19亿元，产值亿元以上酒企增至28家。在这千亿产值的背后，仁怀正在推进一项雄心勃勃的战略——\'六链协同\'。  ## 什么是"六链协同"  仁怀提出的\'六链协同\'战略，旨在主动融入成渝地区双城经济圈：  **一、联通成渝区域链** 交通先行，打通仁怀至成渝核心城市的快速通道。将茅台镇从\'深山产区\'升级为\'成渝两小时经济圈\'的重要节点。  **二、融入成渝产业链** 酱酒产业与成渝的餐饮、文旅、会展等产业深度融合，共同打造\'白酒+美食+文旅\'的消费生态。  **三、服务成渝生活链** 将酱酒从\'礼品\'和\'宴请\'的场景，拓展到成渝都市人群的日常品质生活，让酱酒成为\'生活方式\'的一部分。  **四、借力成渝创新链** 依托成渝科研院所和高校资源，在微生物研究、智能化酿造、绿色生产等领域开展产学研合作。  **五、协同成渝开放链** 借助成渝作为内陆开放高地的优势，推动酱酒出口和国际化布局，让茅台镇不仅是\'中国的酒都\'，更是\'世界的酒都\'。  **六、衔接成渝生态链** 与成渝共同守护赤水河流域的生态环境，将\'绿水青山就是金山银山\'的理念落实到产区的可持续发展中。  ## 战略意义  \'六链协同\'标志着核心白酒产区的发展逻辑发生根本性转变： - **过去**：内部产能扩张——建更多酒厂、产更多酒 - **现在**：跨区域产业生态整合——链接外部资源、构建价值网络  这是从\'工业化思维\'到\'生态化思维\'的跃迁。对赤水河流域的其他产区（习水、金沙、古蔺等）具有示范意义。  *参考：糖酒快讯报道*` },
      'klg_063': { id: 'klg_063', title: `酱酒品鉴培训探索产教融合，为产业专业化人才体系筑基`, author: `糖酒快讯`, icon: `🎓`, views: 4120, content: `在酱酒市场回归理性的当下，专业人才的培养正在成为行业长远发展的基石。2026年酱酒品鉴专项职业能力试验性培训班在茅台学院顺利结业，为行业人才培养开辟了新路径。  ## 培训概况  - **举办地点**：茅台学院（中国唯一的\'酒学院\'） - **培训内容**：酿造工艺、品评方法、质量标准、行业动态 - **教学方式**：理论与生产实践深度融合 - **学员来源**：全国各地，包括广东、澳门等非传统酱酒消费区域  ## 产教融合模式  这次培训的核心创新在于\'产教融合\'： 1. **师资力量**：茅台学院专业教师授课，兼具学术理论和一线经验 2. **课程设计**：从原料识别到成品品评，覆盖酱酒生产全链条 3. **实践环节**：学员走进茅台镇的酿造车间和酒库，亲身体验制曲、发酵、储存 4. **标准建设**：为全国建立统一酱酒品鉴职业能力标准积累经验  ## 为什么品鉴人才如此重要  酱酒的品鉴不同于一般白酒： - 酱酒香气层次复杂，需要经过专业训练才能准确辨识 - 品鉴能力直接影响产业链的多个环节：原料采购、酿造监控、产品勾调、市场推广 - 消费者教育需要品鉴人才：让更多人\'懂酒\'才能\'爱酒\'  ## 消费者视角  对于普通消费者而言，品鉴培训的意义在于： 1. 建立正确的品鉴方法，不再\'盲喝\' 2. 学会辨别酱酒品质，避免被营销话术忽悠 3. 理解\'空杯留香\'、\'回味悠长\'等专业术语的真实含义 4. 从\'喝酒\'升级为\'品酒\'，提升消费体验  酱酒品鉴人才体系的建设，是酱酒从\'量的扩张\'转向\'质的提升\'的重要支撑。  *参考：糖酒快讯报道*` },
      'klg_064': { id: 'klg_064', title: `仁怀上海再推介：酱酒进入"价值深耕"与"生活方式"新阶段`, author: `糖酒快讯`, icon: `🏙️`, views: 5350, content: `5月17日，\'2026世界酱香白酒核心产区仁怀美酒献华夏\'推介活动在黄浦江畔的上海浦东举办。这不是一次普通的产品推广——仁怀带来的是一场关于\'生活方式\'的宣示。  ## 为什么选择上海  仁怀选择上海作为推介城市，有着深层的战略考量： - 上海是中国最大的消费城市，拥有庞大的高净值人群 - 上海有着成熟的品质消费文化，消费者追求的不是\'便宜\'而是\'值得\' - 上海是国际化的窗口，在上海成功即意味着具备了走向国际的条件 - 上海的年轻消费者更愿意为\'体验\'和\'文化\'买单  ## 从"卖产品"到"卖生活方式"  这是本次推介最核心的信号。仁怀市领导在推介中明确提出： > \'我们不是在卖一瓶酒，我们在推荐一种生活方式——一种懂得慢下来、懂得品味、懂得分享的生活方式。\'  这一转变意味着： 1. **场景拓展**：酱酒不只属于宴请和送礼，它可以出现在朋友小聚、周末微醺、户外露营 2. **消费升级**：从\'喝多\'到\'喝好\'，从\'应酬\'到\'享受\' 3. **文化融入**：酱酒与美食、音乐、艺术、旅行等生活方式元素深度结合  ## 产区竞争的升维  酱酒产区之间的竞争，正在经历三个阶段的演进： - **1.0时代**：品类普及——\'什么是酱酒？酱酒有什么好处？\' - **2.0时代**：产能宣讲——\'我们有多少窖池，产能多少吨\' - **3.0时代**：文化渗透——\'喝酱酒是一种什么样的生活方式？\'  仁怀此次的上海推介，正是抢先进入了3.0时代的竞争。  ## 对消费者的意义  当产区不再只谈\'产量\'和\'技术\'，而是开始谈\'生活方式\'和\'文化价值\'，意味着： 1. 消费者买到的不再只是一瓶酒，而是一种文化体验 2. 酱酒的价格将越来越多地体现\'文化附加值\' 3. 懂酒、爱酒的消费者将成为品牌最重要的资产  ## 酱酒行业的新风向  仁怀的\'生活方式\'战略，与茅台提出的\'卖酒向卖生活方式转变\'一脉相承。这预示着整个酱酒行业正在从\'制造业思维\'向\'服务业思维\'和\'文化创意产业思维\'升级。  *参考：糖酒快讯报道*` },
      'klg_065': { id: 'klg_065', title: `中国酒业十五五发展实施方案正式发布：白酒聚焦文化重塑、智能酿造与国际化`, author: `中国网财经`, icon: `📋`, views: 7280, content: `5月21日，中国酒业协会第六届理事会第八次(扩大)会议在北京召开，《中国酒业十五五发展实施方案(2026-2030)》正式发布。  ## 行业诊断：传统增长逻辑与新消费需求的错配  宋书玉理事长指出，产业已进入深度结构性调整期。白酒产量、销售收入与利润均同比下降，依赖增量市场和高端政务商务消费驱动的传统增长模式已难以为继。产业集中度进一步提升，市场份额加速向头部企业聚集。  ## 四大战略机遇与四大挑战  《方案》明确： - **战略机遇**：政策红利释放、消费升级深化、科技动能激发、文化复兴大势 - **严峻挑战**：供需矛盾突出、合规约束趋严、渠道变革加速、竞争加剧  ## 八大核心任务  涵盖标准体系建设、质量安全、科技创新、人才强基、协同生态、公共服务、文化提升和品牌培育。  ## 白酒三大攻坚战  《方案》赋予白酒引领产业价值突破的使命，聚焦三大攻坚战：  **1. 文化价值重塑** 构建能与消费者产生情感共鸣的完整叙事体系。酱酒不仅是一瓶酒，更是一种文化体验和生活方式。  **2. 智能酿造升级** 积极拥抱AI等新质生产力赋能全产业链。从经验酿造向科学酿造精进，实现智能制造和数字化管理。  **3. 国际化突破** 推动白酒标准进入ISO或CAC立项，让中国白酒真正走向世界主流消费市场。  ## 对酱酒从业者的启示  行业将从规模竞争全面转向价值竞争，品质、文化和科技将成为新的核心竞争要素。去库存、稳价格是短期任务，系统性价值重构是长期方向。  *参考：中国网财经、中国酒业协会CADA*` },
      'klg_066': { id: 'klg_066', title: `茅台ESG进阶之路：首次入选标普可持续发展年鉴，藏着中国企业价值升维的密码`, author: `酒业家`, icon: `🌍`, views: 6820, content: `标普全球CSA发布《可持续发展年鉴（中国版）2026》，茅台首次成为入选企业，获饮料行业最佳进步企业，评分提升至60分。本次1800家中国企业仅190家入选。此前2025年MSCI已将茅台ESG评级提升至A级，为全球白酒行业首家。  ## 环境：赤水河生态的全流程守护  茅台将赤水河流域生态视为酿酒根基： - 实施全流程碳管控，确保赤水河水质稳定达地表水II类以上 - 2025年实现绿色电力100%覆盖 - 单位产品耗水较2023年降低32.40%，提前达成2026年节水目标 - 累计投入超4亿元用于流域系统性保护治理  ## 社会：反哺产业链，践行公益  - 通过公司+合作社+农户模式保障高粱种植户收益，带动超12万户农户增收16.4亿元 - 将酒糟转化为有机肥料，年供应约9万吨反哺种植基地 - 中国茅台·国之栋梁连续14年，累计捐赠超14亿元，帮助超26万名学子 - 三次斩获中华慈善奖  ## 治理：ESG嵌入企业战略  - 2024年引入双重重要性框架，设定短中长期量化目标 - 2025年将ESG治理嵌入智慧茅台2.0，实现战略、预算、绩效一体化  ## 对行业的启示  茅台以ESG为支点，从单向给予转向多维共创。生态不是额外负担，而是品牌价值的物质基础和长期竞争壁垒。对中国品牌全球化而言，ESG是必须跨越的价值门槛。  *参考：酒业家报道*` },
      'klg_067': { id: 'klg_067', title: `习酒重磅福利：800网点+10万瓶赠酒，以餐酒联动开启营销2.0新变革`, author: `酒业家`, icon: `🍽️`, views: 6150, content: `即日起至11月21日，习酒全面启动窖藏里的三餐四季订餐赠酒福利活动。联合美团、大众点评覆盖全国超800家优质餐饮门店，投入近10万瓶赠酒。  ## 精准触达C端的三重福利  消费者在平台购买指定套餐并到店消费，可享受： 1. **餐费折扣**：直接降低消费门槛 2. **赠酒福利**：获赠53%vol习酒·窖藏VIP鉴赏II（2026）375ml 3. **抽奖机会**：赢取大额优惠券  活动精准锁定每周五、周六及端午、中秋等假日消费高峰。  ## 从寻味之旅到常态化餐酒联动  自去年7月以来，中华美食寻味之旅从北京出发，走过西安、济南、成都等12座城市。此次活动从城市巡礼升级为覆盖全国、高频持续的消费场景渗透——核心从触达消费者向陪伴消费者转变。  ## 营销2.0改革的战略落子  习酒自2025年底持续推进组织与营销体系调整： - 成立品牌推广中心、营销中心、数据运营中心三大职能机构 - 迈出从卖酒到卖生活方式转型的战略实践 - 将全国800余家餐饮网点转化为体验与销售终端  ## 行业启示  习酒此举为白酒行业做透生活场景贡献了标杆：用折扣+赠酒+抽奖的多重福利降低体验门槛，通过线上线下整合传播进行价值输出，让品牌在消费者真实的用餐场景中自然融入。  *参考：酒业家报道*` },
      'klg_068': { id: 'klg_068', title: `仁怀白酒行业警示教育大会：零容忍守护产区金字招牌，茅台董事会平稳换届`, author: `酒业家`, icon: `⚖️`, views: 5980, content: `5月20日以来，酱酒行业迎来三件治理层面的大事。  ## 仁怀：以警示教育守护产区金字招牌  仁怀全市白酒行业警示教育大会召开。市长陈清松指出：**酱香白酒是仁怀的立市之本、强市之基。**  会议强调三大要求： 1. **坚守食品安全底线**：杜绝不合格产品流入市场 2. **规范市场经营秩序**：坚持依法经营、诚信经营 3. **保持高压态势**：全覆盖从严排查、全链条源头严管、全手段从严惩戒  陈清松特别强调：对违法违规行为零容忍，坚决斩断违法违规黑色利益链。这意味着仁怀作为酱酒核心产区，正在从政府层面建立更严格的产区治理体系。  ## 茅台：董事会平稳换届  贵州茅台公告： - 提名陈华、王莉、周雪为第五届董事会董事候选人 - 提名郭田勇、盛雷鸣、王鑫为独立董事候选人 - 聘任余思明为董事会秘书  管理层平稳过渡，延续陈华时代的战略方向。  ## 郎酒：深耕河南样板市场  古蔺青花郎公司总经理易明亮调研河南盛林，指出河南是郎酒全国化布局的核心腹地。将依托原产地体验与圈层运营，以酒得劲联盟专柜为载体、龙马宴为抓手，构建高端酱酒可持续增长的新路径。  三大信号共同指向一个方向：酱酒行业正在从粗放扩张走向精细化治理。  *参考：酒业家报道*` },
      'klg_069': { id: 'klg_069', title: `山海同酿 侨情共悦：茅台2026年茅友嘉年华在广东赤坎古镇启幕`, author: `糖酒快讯`, icon: `🎪`, views: 5680, content: `5月21日，恰逢小满时节，贵州茅台2026年茅友嘉年华在广东江门开平市赤坎古镇启幕。茅台集团党委书记、董事长陈华出席并致辞。  ## 陈华三点分享  **——以守拙如初的匠心。** 茅台将持续深耕15.03平方公里核心产区，守护不可复制的微生物生态，坚守历经千年淬炼的传统酿造工艺，让每一瓶茅台酒都经得起时光检验。  **——以感恩同行的初心。** 深挖中华优秀传统文化，将东方美学、传统节气、非遗技艺融入品牌叙事与产品设计，坚持消费者在哪里，茅台的服务就延伸到哪里。  **——以同心筑梦的担当。** 茅台与茅友相聚侨都，既是酱香之约，更是情怀之聚、责任之盟。希望与广大茅友一道，传承中华文脉、赓续家国情怀。  ## 沉浸式文化体验  游园探索环节，铛铛车、摇橹船、茅台侨批信局、茅台大事记问答挑战、舞台剧表演等活动，让茅友体验侨情与茅台共生，匠心与初心同行。  ## 为什么选择广东侨乡  赤坎古镇是著名侨乡，海外华侨超75万。茅台选择这里，寓意深远： - 侨乡文化与中国白酒文化有天然的"家国情怀"共鸣 - 广东是茅台最大的省外市场之一 - 通过侨乡连接海外，为茅台的国际化铺设文化通道  茅友嘉年华火炬交接后，下一站将奔赴四川。  *参考：糖酒快讯、贵州茅台*` },
      'klg_070': { id: 'klg_070', title: `十一省区消协联合警示：直击变种特供酒乱象，酱酒消费急需去伪存真`, author: `糖酒快讯`, icon: `🚫`, views: 5320, content: `5月21日，陕、渝、川、滇、黔等**十一省区消费者协会联合发布消费提示**，剑指近年来变种特供酒这一市场毒瘤。  ## 新型假酒手法更隐蔽  与过去明目张胆的违规标注不同，新型假酒呈现三大特征： - **暗示性伪装**：用暗示性词汇替代直接标注特供，如内部品鉴、专享酒、特殊渠道 - **私域交易**：依托微信群、朋友圈等私域社群渠道，规避监管 - **仿冒外观**：仿冒大牌包装设计，炒作收藏概念，隐蔽性和迷惑性大幅增强  消协明确声明：**市面流通特供、专供类酒水均为假货。**  ## 三管齐下根治顽疾  **1. 监管层面**：保持高压态势，实施全链条穿透式监管 **2. 企业层面**：产区与品牌方加强渠道管控与产品溯源能力 **3. 消费者层面**：摒弃投机心理，认准正规渠道——不再为内部酒、特殊渠道等话术所惑  ## 为什么酱酒消费者要特别警惕  酱酒因其品牌溢价高、老酒收藏热，是特供酒造假的重灾区： - 茅台、习酒、郎酒等品牌被仿冒最严重 - 所谓军区特供、机关专供茅台均为假货 - 真正的茅台、习酒等正规酒企从未生产特供酒  这场打假之战，是酱酒行业净化必须打赢的尊严之战。它不仅涉及食品安全，更严重侵蚀消费者对仁怀等核心产区与酱酒品牌的信任基础。  *参考：糖酒快讯、十一省区消协联合发布*` },
      'klg_071': { id: 'klg_071', title: `1-4月白酒产量下降2.8%：行业调整持续，茅台续签商标许可协议释稳健信号`, author: `酒业家`, icon: `📊`, views: 4980, content: `中酒展日报汇编5月22-23日行业核心数据与动态。  ## 行业产量：白酒持续收缩  据国家统计局数据： - 1-4月全国规上白酒产量119.8万千升，**同比下降2.8%** - 4月单月产量24.7万千升，降幅扩大至8.2% - 啤酒产量1195.7万千升，同比增长2.9% - 葡萄酒产量2.7万千升，同比下降6.9%  白酒产量持续收缩，反映行业仍处于深度调整阶段。消费者少喝酒、喝好酒的趋势不可逆转。  ## 茅台续签商标许可协议  贵州茅台公告：与茅台集团续签《商标许可协议》，新协议期限为**2027年1月1日至2029年12月31日**，商标许可使用费比例为1.5%，按季度支付。续签三年协议，释放稳健经营信号。  ## 泸州老窖：国窖1573兼顾价格与动销  2025年度业绩说明会上表示：2026年产品动销和开瓶情况改善，渠道库存压力逐步缓解。国窖1573将合理调节投放节奏、优化库存结构，兼顾价格稳定与市场动销。  ## 酒鬼酒：三大产品线多渠道挖掘新增量  2026年策略：高端聚焦内参核心单品，次高端做强红坛主攻宴席市场，大众酒完善口粮酒布局，同时拓展电商、即时零售、私域等新零售渠道。  ## 对酱酒从业者的启示  产量下降不等于市场萎缩——高端酱酒的需求仍然强劲，关键在于品质和品牌。头部企业通过精细化管理、渠道优化和产品结构升级应对调整期，这正是酱酒行业需要学习的方向。  *参考：酒业家中酒展日报、国家统计局*` },
      'klg_072': { id: 'klg_072', title: `守一河清水，护万物共生：茅台生态公益再出发`, author: `酒业家`, icon: `🌿`, views: 5200, content: `在5月22日国际生物多样性日之际，茅台集团以实际行动诠释生态优先、绿色发展的企业理念。  ## 赤水河：酱酒的生命之源  赤水河是长江上游唯一未建水坝的一级支流，水质常年保持II类标准。对于茅台和整个酱酒产业而言，赤水河不仅是地理意义上的母亲河，更是品质的根本保障。  ## 茅台的生态实践  ### 水资源保护 - 茅台投资建设高标准污水处理厂，酿酒废水100%达标排放 - 建立赤水河流域水质自动监测网络，实时监控水质变化 - 推广节水工艺，单位产品用水量持续下降  ### 生物多样性维护 - 茅台核心产区15.03平方公里内已发现1946种微生物 - 设立赤水河鱼类保护区，增殖放流珍稀鱼类 - 保护沿岸原生植被，森林覆盖率保持在55%以上  ### 碳中和路径 - 茅台制定碳中和路线图，推进清洁能源替代 - 酒糟资源化利用：转化为有机肥、饲料、生物质能源 - 推广绿色包装，减少塑料使用  ## 行业的生态共识  仁怀市已投资85亿元用于赤水河流域水环境治理，沿岸污水处理率达到95%以上。茅台作为行业龙头，在生态保护方面的投入和示范效应，正在带动整个酱酒产业走向绿色可持续发展之路。  ## 为什么生态保护关系到每一瓶酒  水质、空气、土壤、微生物——每一个环境因素都直接影响酱酒的品质。保护赤水河流域的生态环境，就是保护酱酒产业的未来，也是保护每一瓶茅台酒的品质根基。  *参考：酒业家报道*` },
      'klg_073': { id: 'klg_073', title: `茅台连续十年参展济南中酒展：全系产品集结亮相，为行业注入信心`, author: `酒业家`, icon: `🎪`, views: 4800, content: `6月26日-28日，2026第15届（济南）中国高端酒展览会将在山东国际会展中心盛大举办。茅台集团已正式确认参展，这将是茅台连续第十年亮相该展会。  ## 参展阵容：全系产品集结  本次茅台将集结旗下五大酒业公司集体亮相（展位号：3N27）： - 茅台酒销售公司：飞天茅台、精品茅台、年份酒等核心产品 - 茅台酱香酒营销公司：茅台1935、汉酱、王子酒等系列酒 - 茅台保健酒业公司：大众酱香与酱香露酒双赛道产品 - 茅台葡萄酒业公司：茅台葡萄酒系列 - 赖茅酒业公司：赖茅品牌产品  ## 展会规模  - 时间：2026年6月26日-28日 - 地点：山东国际会展中心（距济南西站仅1公里） - 规模：3大展馆、12+品类、1600+展商 - 茅台展位：3N27  ## 十年参展的意义  ### 行业信心信号 在当前白酒行业深度调整期，茅台连续十年参展释放了积极信号：头部企业对行业长期发展充满信心，愿意与全行业共享发展成果。  ### 市场化改革展示 本次茅台集结全系产品参展，也是其推进市场化改革的一次集中展示。从茅台酒到系列酒，从白酒到葡萄酒，茅台正在以更开放的姿态拥抱市场和消费者。  ### 行业交流平台 中酒展已成为中国酒业最具影响力的专业展会之一。茅台与五粮液、泸州老窖、汾酒等名酒企业同台亮相，为经销商和消费者提供了全面了解中国酒业最新动态的窗口。  ## 对酱酒行业的影响  茅台连续十年参展，不仅展示了企业自身的发展成果，也带动了整个酱酒品类的关注度。在当前行业调整期，这种持续性的品牌投入有助于稳定市场预期，推动酱酒产业的健康发展。  *参考：酒业家报道*` },
      'klg_074': { id: 'klg_074', title: `中国酒业“十五五”发展实施方案正式发布，酱酒产业迎来高质量发展新阶段`, author: `中国酒业协会`, icon: `📋`, views: 0, content: `## 产业蓝图：从规模扩张到价值深耕  2026年5月21日，中国酒业协会第六届理事会第八次（扩大）会议在北京隆重召开。会上，《中国酒业“十五五”发展实施方案（2026-2030）》正式发布，为酒业未来五年行动绘就了具体路线图。  这份纲领性文件直面中国酒业从**增量市场向存量市场过渡、从规模扩张向价值深耕转型**的关键命题，系统回答了产业“往哪里走、怎么走”的核心问题。  ### 白酒产业的核心任务  《方案》赋予白酒**引领产业价值突破**的使命，聚焦三大攻坚战： - **文化价值重塑**：深入挖掘白酒文化内涵，构建能与消费者产生情感共鸣的完整叙事体系 - **智能酿造升级**：推动传统技艺与智能制造的并行发展，提升全产业链效率 - **国际化突破**：加快中国白酒的全球市场布局  ### 产业形势研判  宋书玉理事长指出，当前产业面临“量价齐跌、库存高企”等挑战，本质是“传统增长逻辑与新消费需求之间的系统性错配”。短期内须着力**去库存、稳价格**；长期则必须依托“文化、科技、消费”三轮驱动，完成系统性价值重构。  产业集中度进一步提升，市场份额加速向头部企业聚集。**以茅台为代表的酱酒核心产区**在品牌价值和市场集中度方面持续领先，同时也面临消费场景变革和渠道重构的深刻挑战。  *参考：中国酒业协会第六届理事会第八次（扩大）会议报道，https://www.cada.cc/Item/1542.aspx*` },
      'klg_075': { id: 'klg_075', title: `2026年全国酒业协会座谈会：酱酒产区如何应对理性消费时代`, author: `中国酒业协会`, icon: `🏛️`, views: 0, content: `## 变局中的酱酒产区：从“站台”到“站岗”  2026年5月20日，由中国酒业协会主办的“2026年全国酒业协会负责人座谈会”在北京召开。会议指出，当前中国酒业正处在**“十五五”开局见机、产业深度调整**的关键节点。  ### “三理性”时代的挑战  会议明确提出，国内消费已全面迈入**“理性消费、理性饮酒、理性发展”**的“三理性”新阶段。对酱酒产业而言，这意味着：  - **传统政务与商务宴饮场景明显收缩**，依赖高端礼品和商务消费的增长模式难以为继 - **产能过剩与库存高企**成为行业共性难题，部分中小酱酒企业面临生存压力 - **消费场景重塑**，基于个人情绪满足、家庭小聚、户外轻社交等新兴场景正在崛起  ### 协会角色转型  宋书玉理事长强调，协会的角色定位必须从**“站台”转向“站岗”，从“指导”转向“参与”**。对仁怀等酱酒核心产区而言，这意味着：  - 强化产区品牌建设，推动酱酒产区标准体系完善 - 深化产城融合，以酒旅融合带动产区经济多元发展 - 精准链接消费者，打造面向C端的酱酒文化体验IP  何勇秘书长系统阐述了“GBC”服务能力——高效服务政府（Government）、深度赋能行业企业（Business）、精准链接消费者（Consumer），为酱酒产区的转型升级提供了方向指引。  *参考：2026年全国酒业协会负责人座谈会报道，https://www.cada.cc/Item/1543.aspx*` },
      'klg_076': { id: 'klg_076', title: `习酒接棒酒与社会责任当值理事长单位，倡导适量饮酒快乐生活`, author: `中国酒业协会`, icon: `🍶`, views: 0, content: `## 酱酒龙头共担社会责任  2026年5月22日，中国酒业协会酒与社会责任促进工作委员会秘书长会暨酒与社会圆桌会在北京成功召开。**贵州茅台、贵州习酒、泸州老窖、洋河**等酒业龙头企业的代表齐聚一堂，共商酒业社会责任发展大计。  ### 习酒接棒当值  贵州习酒投资控股集团有限责任公司党委书记、董事长汪地强代表2026年当值理事长单位发言。他指出，**酒业的高质量发展不仅在于酿造高品质的美酒，更在于向社会传递适度、健康、科学的饮酒方式**。  习酒秉承“崇道、务本、敬商、爱人”的核心价值观，践行“知敬畏、懂感恩、行谦让、怀怜悯”的君子品格，在多个领域协同发力： - 坚持“绿水青山就是金山银山”发展理念，走生态优先、绿色发展之路 - 连续开展“习酒·我的大学”公益奖学助学项目 - 持续通过“习酒·吾老安康”慈善基金关爱护林员群体  ### 茅台代表出席  贵州茅台酒厂（集团）有限责任公司党委宣传部副部长丁娜出席会议。茅台作为中国酱酒产业龙头企业，始终在ESG体系建设和理性饮酒推广方面发挥引领作用。  ### 2026年主题：适量饮酒、快乐生活  委员会将以“**适量饮酒、快乐生活**”为年度主题，首次联合中央电视台电影频道策划推出系列公益短剧，并举办“美酒美生活”短视频大赛，以年轻化、场景化的内容触达新一代消费者。会议还计划发布《2026中国适量饮酒快乐生活蓝皮书》，为倡导理性适度饮酒提供权威数据与理论支持。  *参考：2026年中国酒业协会酒与社会责任圆桌会报道，https://www.cada.cc/Item/1545.aspx*` },
      'klg_077': { id: 'klg_077', title: `茅台ESG进阶之路：从酱酒龙头到中国企业价值升维的典范`, author: `酒业家团队`, icon: `🌿`, views: 0, content: `## 从赤水河到ESG：茅台的可持续发展密码  茅台作为中国酱酒产业的绝对龙头，其ESG（环境、社会和治理）实践正成为中国企业价值升维的重要参照。  ### 守护赤水河：酱酒的生命线  赤水河是酱香白酒的“母亲河”，其独特的水质和微生物环境是酿造优质酱酒不可替代的自然条件。茅台坚持**“守一河清水，护万物共生”**的生态理念，将赤水河流域生态保护置于企业战略核心：  - 投资建设污水处理设施，确保酿造废水达标排放 - 推进赤水河流域生物多样性保护项目 - 建设绿色供应链体系，推动上游有机高粱种植的生态化转型  ### ESG体系构建  茅台在ESG体系建设方面走在行业前列： - **环境（E）**：推进清洁能源使用，降低碳排放强度，保护赤水河流域生态环境 - **社会（S）**：助力乡村振兴，带动仁怀及周边地区高粱种植户增收；持续开展教育公益项目 - **治理（G）**：完善市场化运营机制，推动茅台酒与系列酒差异化定位  ### 行业引领价值  在中国酒业协会酒与社会责任圆桌会上，茅台ESG实践被作为行业标杆进行讨论。茅台的经验表明，**酱酒产业的高质量发展必须建立在生态可持续的基础上**，ESG不是成本而是竞争力。  宋书玉理事长强调，ESG工作重点将从“建标准”转向“出实效”，茅台等龙头企业将继续引领行业ESG评级体系的完善和推广。  *参考：酒业家《茅台ESG进阶之路》报道，https://www.jiuyejia.com/*` },
      'klg_078': { id: 'klg_078', title: `中国酒业品牌创意专委会成立，十五五品牌建设2030行动计划启动`, author: `中国酒业协会`, icon: `🎨`, views: 0, content: `## 酱酒品牌进入3.0时代  2026年5月22日，以“品创·融变”为主题的中国酒业协会品牌创意专业委员会成立大会暨品牌创新工作交流会在京举行。大会汇聚了来自**酿酒生产企业、品牌创意机构、包装设计单位、营销策划公司及高校院所**的百余名代表。  ### 品牌3.0：从企业品牌到消费者共创  中国酒业协会秘书长何勇在致辞中指出，中国酒业已经进入**品牌3.0时代**——品牌不再是企业的品牌，而是企业与消费者共创的、共享的精神资产。对于酱酒产业而言，这意味着：  - 从“渠道驱动”转向“品牌驱动”和“用户驱动” - 酱酒品牌需要构建能与消费者产生情感共鸣的完整叙事体系 - 包装设计、文化传播和消费体验的全面升级  ### 2030行动计划  专委会秘书长潘耀平发布了《中国酒业“十五五”品牌建设2030行动计划纲要（草案）》，规划了包括**十大实施路径**的品牌建设体系。《酿酒产业提质升级指导意见》明确提出要培育100个知名品牌，酱酒核心产区的品牌建设迎来政策红利。  ### 文化赋能酱酒品牌  大会还举行了中国酒业协会与景德镇昌南新区管委会战略合作签署仪式，探索**传统陶瓷工艺与现代酒类品牌美学**的创新融合。这对以茅台为代表的酱酒品牌具有特殊意义——酱酒的品牌价值不仅在于品质，更在于其承载的中国传统文化底蕴。  *参考：中国酒业协会品牌创意专业委员会成立大会报道，https://www.cada.cc/Item/1546.aspx*` },
      'klg_079': { id: 'klg_079', title: `酱香白酒核心工艺：从端午制曲到重阳下沙的传统密码`, author: `酱酒知识库`, icon: `🏺`, views: 0, content: `## 酱酒工艺的12987密码  酱香型白酒以其独特复杂的酿造工艺被誉为中国白酒工艺的“活化石”。其核心工艺遵循传统的**12987**古法：  ### 工艺解析  - **1年生产周期**：从端午制曲到次年重阳完成取酒，耗时整整一年 - **2次投料**：重阳下沙（第一次投料）和糙沙（第二次投料） - **9次蒸煮**：原料经过反复蒸煮，充分释放淀粉和风味物质 - **8次发酵**：每次蒸煮后堆积发酵，利用赤水河流域特有的微生物菌群 - **7次取酒**：分轮次取酒，每轮次酒体风格各异，最终勾调成统一风味  ### 核心要素  酱酒品质取决于四大核心要素：  - **赤水河**：独特的水质和矿物质含量是酿造酱酒不可替代的水源基础 - **红缨子高粱**：仁怀本地特有的有机糯高粱，皮厚、支链淀粉含量高，能经得起九次蒸煮 - **酿酒微生物**：茅台镇独特的地理环境和气候条件，孕育了不可复制的微生物菌群 - **时间沉淀**：基酒需经至少3-5年的陶坛贮存，方能去除燥辣，呈现酱香突出、幽雅细腻的风格  ### 仁怀核心产区  仁怀市作为中国酱香白酒核心产区，拥有SC认证的酒厂506家（截至2024年数据），形成了以茅台为龙头、国台、钓鱼台等为骨干的产业集群。**赤水河流域15.03平方公里的茅台镇核心产区**，是全球唯一的优质酱香型白酒产地。  *参考：中国酒业协会行业资料及酱酒产区公开信息*` },
      'klg_080': { id: 'klg_080', title: `酱酒品鉴入门：观色、闻香、品味三步读懂一杯好酱酒`, author: `酱酒知识库`, icon: `🥃`, views: 0, content: `## 三步品鉴法：解锁酱酒风味密码  酱香型白酒是中国十二大香型白酒中风味最复杂的一种，其品鉴需要专业的方法和耐心的体验。  ### 第一步：观色  将酒倒入透明品酒杯中，举杯齐眉，观察酒体： - **色泽**：优质酱酒应呈微黄色、清澈透明、无悬浮物和沉淀 - **挂杯**：轻轻摇晃酒杯，酒液挂杯形成的“酒泪”越明显，说明酒体越醇厚 - **年份参照**：新酒一般无色透明，随着陈年时间增长，酒体微黄程度会逐渐加深  ### 第二步：闻香  酱酒的香气层次极为丰富，品鉴时可将酒杯置于鼻下1-3cm处： - **前香**（头香）：初闻酱香突出，带有焦香、糊香的复合气息 - **中香**（体香）：细闻可辨识花果香、烘焙香、坚果香等多层次香气 - **空杯留香**：饮尽后放置片刻再闻空杯，优质酱酒的空杯留香持久，可达24小时以上  ### 第三步：品味  小口抿入，让酒液铺满舌面： - **入口**：优质酱酒入口醇厚绵柔，不刺喉、不烧心 - **中段**：酒体丰满，酸甜苦辣咸五味协调，层次分明 - **回味**：下咽后回甘悠长，余味可停留数分钟  ### 品鉴温度  酱酒最佳品鉴温度为**21-25℃**。温度过低会锁住香气，过高则酒精刺激感过强。建议使用郁金香形品酒杯，能更好地聚集香气。  *参考：中国酒业协会品酒师培训教材及酱酒行业品鉴指南*` },
      'klg_081': { id: 'klg_081', title: `仁怀酱酒产区：从中国酒都到世界酱香白酒核心产区`, author: `酱酒知识库`, icon: `🗺️`, views: 0, content: `## 仁怀：一座飘着酒香的城市  仁怀市位于贵州省西北部、赤水河中游，是云贵高原向四川盆地过渡地带，面积1788平方公里。这座被誉为**中国酒都**的县级市，2023年GDP达到1800.32亿元，是贵州省唯一过千亿的县域经济体。  ### 506家酒厂的产业版图  截至2024年，仁怀市共有**506家SC获证酒厂**，形成了以贵州茅台为绝对龙头，国台、钓鱼台、金沙等为骨干，众多中小酒企为依托的金字塔型产业集群。这些酒厂集中在赤水河流域，构成了**全球唯一的优质酱香白酒核心产区**。  ### 独特的地理禀赋  仁怀能够成为世界酱酒核心产区，得益于不可复制的自然条件：  - **赤水河**：全长436公里的赤水河是长江上游唯一未建水坝的一级支流，水质纯净、矿物质丰富 - **气候条件**：冬暖夏热、少雨少风的河谷气候，极有利于酿酒微生物的生长繁殖 - **地质结构**：紫红色土壤富含砂质和砾石，渗透性强，为酿酒提供了优质的水源过滤系统 - **微生物菌群**：经过数百年酿酒活动，茅台镇的空气中已形成独特且稳定的微生物生态系统  ### 产区的战略升级  2026年5月，仁怀酱酒同时布局上海与香港市场，推动**酱酒的国内外双向拓展**。仁怀市正从“中国酒都”向“世界酱香白酒核心产区”的战略定位迈进。  在“十五五”规划指引下，仁怀酱酒产区将重点推进：标准体系完善、智能酿造升级、酒旅融合发展和国际市场开拓，力争到2030年建成具有全球影响力的世界级白酒产业集群。  *参考：仁怀市人民政府公开信息、央广网报道（2026年5月19日）*` },
    }
    const local = localArticles[route.params.id]
    if (local) {
      article.value = local
    } else {
      article.value = { title: '文章不存在', author: '', views: 0, content: '抱歉，您访问的文章不存在。' }
    }
  } finally {
    loading.value = false
  }
})
</script>

